(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-chunked-prefill-piggyback-rollout"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-1\">一 · 事故现场：一次被串行 prefill 拖垮的 rollout 批次</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-2\">二 · 它精确解决的是什么：时间维度上的瓶颈互补</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-3\">三 · 适用边界：什么时候它有效，什么时候它失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-4\">四 · chunk_size 这一个人为常数如何决定成败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-5\">五 · 时延抖动：被牺牲的那部分稳定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-6\">六 · 一个具体例子：512 token 的 chunk 如何填满一个 step</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-7\">七 · 搭载失效的三种现场与边界判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-8\">八 · 从调度器到待搭载队列：chunk 的切分与入队</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-9\">九 · 搭载批的构成：两类 workload 拼成同一 batch</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-10\">十 · 单步前向：decode 单 token 与 chunk 内因果 attention 的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-11\">十一 · KV 落表与请求状态迁移：chunk 完成后的块表合并</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-12\">十二 · 队列耗尽与批次收尾：统计回传的时点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-13\">十三 · 步骤间的耦合代价：chunk_size 作为全局旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-14\">十四 · 搭载批的边界条件与失效代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-15\">十五 · 搭载批的构成与逐项含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-16\">十六 · 从互补到 T_step：关键一步推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-17\">十七 · 伪代码：从队列到块表并入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-18\">十八 · chunk_size 的定量取舍与抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-19\">十九 · 队列积压：互补对象消失的失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-20\">二十 · 搭载批的边界：互补失效、抖动代价与队列积压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-21\">二十一 · 搭载批的边界：互补失效与抖动代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-22\">二十二 · 请求形态：什么样的 rollout 批次才喂得饱搭载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-23\">二十三 · 长度分布与 chunk_size 的匹配关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-24\">二十四 · 并发与批大小：decode 集合规模决定收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-25\">二十五 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-26\">二十六 · 与相邻机制的负载分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-27\">二十七 · 负载配方：互补窗口的边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-28\">二十八 · 负载配方：互补成立的前提与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-29\">二十九 · 硬件档位：先定“谁和谁同卡”，再定卡型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-30\">三十 · 并行拓扑：TP 与 EP 的取舍由 chunk 的 attention 形态决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-31\">三十一 · 量化方案：搭载批内两类 workload 必须同精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-32\">三十二 · KV 策略：块表合并时机与分页粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-33\">三十三 · 调度参数：chunk_size 与 decode 集合规模的联动调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-34\">三十四 · 可复现配置思路：从瓶颈项反推，而不是从参数表照抄</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-35\">三十五 · 搭载配方的边界：互补失效的三种工况与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-36\">三十六 · 搭载批的显存账：谁在占，谁在等</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-37\">三十七 · 带宽与算力的互补率：MFU 公式里的第二项什么时候咬人</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-38\">三十八 · 权重加载的共享边界与 L2 行为</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-39\">三十九 · 通信：单引擎省掉的与规模上去后新增的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-40\">四十 · 功耗与热：互补不等于省电</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-41\">四十一 · 尾延迟与规模先崩点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-42\">四十二 · 搭载批的临界规模与失效链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-43\">四十三 · 精度漂移：搭载批内两类 workload 的数值一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-44\">四十四 · OOM 的三条路径与块表水位监控</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-45\">四十五 · 批抖动与路由不均：抖动源在 chunk 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-46\">四十六 · 尾延迟尖刺：token 级超时误杀长尾样本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-47\">四十七 · 监控面与回滚开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-48\">四十八 · 搭载失效的五种形态与可观测抓手</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-49\">四十九 · 搭载失效的四种形态与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-50\">五十 · 同族算法的选择维度：先问“瓶颈在哪一侧”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-51\">五十一 · 与前缀 KV 共享的分工：空间复用 vs 时间互补</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-52\">五十二 · 与分离式预填/解码的取舍：抖动预算换部署复杂度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-53\">五十三 · 与在线剪枝的边界：提效不等于改分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-54\">五十四 · 决策表：把适用条件压成可执行的判断链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-55\">五十五 · 规模上限与工程判断的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-rollout-sec-56\">五十六 · 搭载法的失效边界与同族算法选型判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:534px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 534.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout调度器将新到的长prompt按chunk_size（如512…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每个decode iteration从队列取一个chunk，与当前所有在跑…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">模型对batch内decode token做单步前向、对chunk tok…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">chunk执行完后其KV块并入对应请求的块表，该请求转入decode集合；…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">当decode集合为空且队列清空时rollout批次结束，统计每请求的to…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-1\">一 · 事故现场：一次被串行 prefill 拖垮的 rollout 批次</h3>\n<p>某 RL 训练任务在 GB200 NVL72 单机上跑 rollout，策略模型每轮要处理一批长短差异极大的 prompt：一部分是几百 token 的短指令，另一部分是数千 token 的长文档加多轮历史。调度器最初采用最朴素的策略——先把所有新到 prompt 的 prefill 集中跑完，再让这批请求一起进入 decode。事故发生在一次 prompt 长度分布突然右移的批次上：长 prompt 的 prefill 阶段把 SM 打得接近饱和，但 HBM 带宽读数长期停在低位，因为 prefill 是算力密集、每字节权重承载的 FLOPs 远高于 decode；等到 prefill 全部结束转入 decode，画风立刻反转——decode 每步只处理一个 token，算力大量闲置，瓶颈完全落在 HBM 带宽上，SM 占用率掉到很低。整个 rollout 批次被拉长，训练侧等待样本回传的时间超出预期，而 GPU 在两段里各浪费了一半的资源：prefill 段浪费带宽，decode 段浪费算力。这个事故不是配置错误，而是串行结构本身决定的：两类互补的瓶颈被时间上切开，永远无法互相填补。</p>\n<p>更具体的代价可以写成一条下界。设一个 step 内 decode 的算力需求为 $F_{\\text{decode}}$、带宽需求为 $B_{\\text{decode}}$，prefill 部分为 $F_{\\text{prefill}}$、$B_{\\text{prefill}}$，串行执行时总时间近似为两段之和，每段各自被自己的瓶颈卡住：</p>\n<div class=\"formula\">$$T_{\\text{serial}} \\approx \\frac{F_{\\text{prefill}}}{P_{\\text{peak}}} + \\frac{B_{\\text{decode}}}{BW_{\\text{HBM}}}$$</div>\n<p>而如果两类 workload 能进入同一个 step，时间下界变成 $\\max$ 而不是 $\\sum$：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>事故批次的教训是：只要 prompt 长度分布是混合的，串行结构就必然在某一侧留下空洞。这正是分块预填搭载解码要解决的问题——它不改变样本集合，不改变模型，只改变同一个 step 内 batch 的构成。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-2\">二 · 它精确解决的是什么：时间维度上的瓶颈互补</h3>\n<p>这个算法针对的推理问题是：在单引擎、同机共卡的 RL rollout 场景下，如何让长 prompt 的 prefill 与正在进行的 decode 共享同一个 batch、同一个 step、同一组权重加载，从而把算力密集段与带宽密集段在时间上叠起来。它的核心动作是把长 prompt 按固定 chunk_size（典型取值 512 token）切成多个 prefill chunk，放进待搭载队列；每个 decode iteration 从队列取一个 chunk，与当前所有在跑的 decode 请求拼成同一 batch。第 $t$ 步的 batch 构成为：</p>\n<div class=\"formula\">$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$</div>\n<p>其中 $\\mathcal{D}_t$ 是第 $t$ 步的 decode 集合，$\\mathcal{Q}_t$ 是待搭载队列，$c_j$ 是第 $j$ 个 chunk 的实际长度。模型对 decode token 做单步前向、对 chunk token 做 chunk 内因果 attention，二者共享同一组权重加载——这一点是关键：权重只从 HBM 读一次，decode 的带宽需求与 prefill 的算力需求在同一段墙钟时间里被消化。chunk 执行完后，其 KV 块并入对应请求的块表，该请求转入 decode 集合；队列里还有 chunk 就继续搭载。当 decode 集合为空且队列清空，rollout 批次结束，统计每请求的 token 与 logprob 回传训练侧。</p>\n<p>它明确不解决的问题有三类。其一，它不消除同一 prompt 的重复预填——那是前缀 KV 共享的职责，本算法只在时间维度把不同 prompt 的 chunk 搭载到 decode step，对跨请求的 KV 复用不做任何事。其二，它不改变样本集合的价值判断——在线剪枝放弃低价值轨迹，而搭载只是提升单引擎利用率，样本该多少还是多少。其三，它不解决分离式部署下的跨节点 prefill/decode 编排——那属于预填解码分离的范畴，本算法的前提恰恰是单引擎同机共卡，不需要也不引入额外的 KV 传输链路。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-3\">三 · 适用边界：什么时候它有效，什么时候它失效</h3>\n<p>适用条件可以收敛成三条，缺一条收益就会塌陷。第一，prompt 长度必须是混合的：如果一批请求全是短 prompt，prefill 本身就很轻，搭载进 decode 的 chunk 提供的算力填充有限；如果全是长 prompt，decode 集合在早期很小甚至为空，搭载失去互补对象。第二，训练与 rollout 同机共卡：单引擎部署意味着 prefill chunk 与 decode 请求天然共享权重与 KV 空间，不需要跨卡搬运；一旦拆成两个引擎，搭载就退化成两个进程间的拼批，收益被通信吃掉。第三，decode 集合要有足够规模：搭载的互补对象是 decode 请求，decode 集合过小，chunk 会独占 batch，此时带宽利用率回落到 prefill 单独执行的水平，互补失效。规模上限受 chunk_size 与 decode 集合规模共同约束，具体上限取决于模型与卡型，没有通用数字。</p>\n<p>失效模式里最隐蔽的一种是队列积压与 decode 收缩同时发生。设想一个批次前半段涌入大量长 prompt，待搭载队列堆了几十个 chunk；后半段短请求陆续完成、decode 集合缩小到个位数。此时每个 step 搭载一个 chunk，batch 里 decode token 寥寥无几，chunk 成为绝对主体——这等价于把 prefill 重新串行化，只是披着搭载的外衣。调度器如果只看队列非空就继续搭载，就会在这个阶段白白丢掉带宽互补，rollout 尾段被拉长。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>满足时</th><th>不满足时</th></tr></thead><tbody><tr><td>prompt 长度混合</td><td>算力与带宽两类瓶颈同 step 互补</td><td>单一长度分布，搭载无对象或填充不足</td></tr><tr><td>单引擎同机共卡</td><td>共享权重加载与 KV 空间</td><td>跨引擎拼批，通信开销吞掉收益</td></tr><tr><td>decode 集合有规模</td><td>chunk 有稳定互补对象</td><td>chunk 独占 batch，带宽利用率回落</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-4\">四 · chunk_size 这一个人为常数如何决定成败</h3>\n<p>chunk_size 是固定超参，也是这个算法最脆弱的工程点。取小了，prefill 被切碎：每个 chunk 的 token 数少，chunk 内因果 attention 的矩阵规模变小，SM 上的 tile 利用率下降，attention 效率损失；同时 chunk 数变多，队列管理、块表合并、每 step 的调度开销按比例上升。取大了，单个 chunk 在 step 内占的算力份额变大，decode 请求被拖慢——decode 的 token 级时延直接受同 batch 内 prefill 工作量影响，chunk 越大，decode step 的墙钟时间越长。这条曲线没有解析最优解，只能按 prompt 长度分布调参：分布右移（长 prompt 变多）时 chunk 可以适度放大以摊薄切碎损失，分布左移时 chunk 应缩小以保护 decode 时延。</p>\n<p>更麻烦的是分布漂移。RL 训练中策略在变，rollout 的 prompt 来源也在变，一个在某一轮调好的 chunk_size，到了下一轮可能完全不匹配。当 chunk_size 与当前分布错位时，互补失效不是渐变而是跳变：chunk 过小则 prefill 段被切得零碎、attention 效率下降，chunk 过大则 decode 被拖慢，两种情况下 $\\max$ 公式里的两项不再平衡，搭载批的 MFU 掉回串行水平附近。工程上的判断是：chunk_size 必须作为随分布监控的量，而不是一次设定就冻结的常量；至少要在 rollout 调度器里保留按批次长度直方图重估 chunk_size 的入口。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-5\">五 · 时延抖动：被牺牲的那部分稳定性</h3>\n<p>搭载带来的第二个代价是 decode step 的时延抖动增大。串行结构下，decode 段的每步时间相对平稳，因为 batch 构成稳定；搭载结构下，每个 step 都混入不同长度、不同来源的 prefill chunk，step 时间随 chunk 的实际 token 数与 attention 形态波动。对以 GPU 利用率为目标的 SLO，这种抖动可以接受；但对 token 级超时判定，它是直接的麻烦来源。rollout 侧通常按 token 间隔设超时，抖动会把正常的长尾样本误判为超时——一个本来只是排在长 chunk 后面的 decode 请求，其单步时延被拉长，触发误杀，长尾统计失真，进而影响训练侧看到的样本分布。</p>\n<p>这里的工程取舍很明确：搭载优化的是批次级吞吐与 MFU，代价是请求级时延的方差。如果下游训练对长尾样本的完整性敏感（例如需要按轨迹长度做加权），就不能只用 token 级超时来判死，而要把超时判定从单步间隔改为滑动窗口内的累计进度，或者对搭载批内的 decode 请求单独放宽阈值。这不是算法本身能解决的，是调度器必须配套的策略。反过来，如果场景对时延抖动零容忍、要求每步时间可预测，那么这个算法就不该被采用——它的收益正是用抖动换来的。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-6\">六 · 一个具体例子：512 token 的 chunk 如何填满一个 step</h3>\n<p>设当前 decode 集合有 32 个请求，每步各生成 1 个 token，合计 32 个 decode token；待搭载队列头部是一个 512 token 的长 prompt chunk。调度器把两者拼成一个 batch 送入模型：decode 部分做单步前向，chunk 部分做 chunk 内因果 attention，权重只加载一次。这个 step 的算力需求由 chunk 的 512 个 token 主导，带宽需求由 decode 的 32 个 token 的 KV 读取加上 chunk 自身的 KV 写入共同构成——两类需求在同一段墙钟时间内被满足，SM 与 HBM 带宽同时处于较高占用。chunk 完成后，其 KV 块并入该长 prompt 请求的块表，该请求从待搭载队列转入 decode 集合，下一步 decode 集合变成 33 个请求，队列取下一個 chunk 继续搭载。</p>\n<p>对比串行执行：同样这批工作，prefill 段单独跑 512 token 时 SM 忙而带宽闲，decode 段单独跑 32 token 时带宽忙而算力闲，两段墙钟时间相加，且每段都有一半资源空转。搭载结构把两段压进一个 step，$T_{\\text{step}}$ 由 $\\max$ 决定而非求和，这就是 MFU 提升的全部来源。需要注意的是，这个例子里的数字只用于说明结构，实际 chunk 长度与 decode 集合规模必须按部署调参；512 是给定事实中的典型取值，不是普适最优。当 decode 集合缩到个位数时，同样的 512 token chunk 就会独占 batch，此时搭载的互补对象消失，调度器应当暂停搭载、先把队列压一压，或者把 chunk 进一步切小以匹配缩小的 decode 集合——这正是适用边界在运行时的具体体现。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-7\">七 · 搭载失效的三种现场与边界判据</h3>\n<p>线上最先暴露的往往不是算力不足，而是<strong>长尾样本被误杀</strong>。某轮 rollout 中，一批长 prompt 的 chunk 被搭载进 decode step，单步时延从稳态被拉高，token 级超时判定把仍在正常推进的长尾请求判为失败并丢弃；训练侧收到的样本分布因此偏向短 prompt，reward 统计出现系统性偏移。这类事故的根因不在数值精度，而在搭载把 decode step 的时延抖动放大：<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>抖动来自 max 的两项随 chunk 长度切换而交替主导，超时阈值按稳态设定就必然误伤。工程判断是：搭载场景下超时判据必须按 step 级而非 token 级设定，或对搭载请求单独放宽。</p>\n<p>第二类失效是<strong>互补对象消失</strong>。待搭载队列积压而 decode 集合因请求陆续完成而缩小时，chunk 找不到可互补的带宽密集 workload，独占整个 batch，HBM 带宽利用率回落到纯 prefill 水平，搭载退化为串行 prefill 还多付了调度开销。可用的判据是搭载批的构成：<div class=\"formula\">$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$</div>当 $|\\mathcal{D}_t|$ 低于某个比例，$\\text{MFU}_{\\text{piggyback}}$ 的分子增量抵不过分母的 step 拉长，收益转负。规模上限受 chunk_size 与 decode 集合规模共同约束，decode 集合过小则收益下降。</p>\n<p>第三类是<strong>分布漂移下的超参失配</strong>。chunk_size 是固定超参，prompt 长度分布一旦漂移（例如训练阶段切换导致长 prompt 占比骤升），512 token 的切分要么把 prefill 切得过碎、chunk 内因果 attention 效率下降，要么单个 chunk 过大拖慢 decode step，两类瓶颈的互补失效。它不解决的问题也应划清：不改变样本集合（那是剪枝的职责），不消除同 prompt 的重复预填（那是前缀 KV 共享的职责），也不适用于 prefill 与 decode 已物理分离的部署——分离式架构下两者本就不共享 SM 与带宽，搭载失去物理基础。适用边界因此收敛为：长短 prompt 混合、训练与 rollout 同机共卡、单引擎部署，且 decode 集合规模足以提供互补对象。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>判据</th></tr></thead><tbody><tr><td>decode 集合缩小</td><td>带宽利用率回落，step 拉长</td><td>$|\\mathcal{D}_t|$ 占比过低</td></tr><tr><td>chunk_size 失配</td><td>attention 效率下降或 decode 被拖慢</td><td>prompt 长度分布漂移</td></tr><tr><td>时延抖动</td><td>长尾样本误杀、统计失真</td><td>token 级超时阈值</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-8\">八 · 从调度器到待搭载队列：chunk 的切分与入队</h3>\n<p>搭载批的起点不在 GPU 上，而在 rollout 调度器的队列结构里。新到的长 prompt 进入系统时并不立即整体预填，而是按 <code>chunk_size</code>（典型取值 512 token）切成若干个定长片段，最后一个片段允许不足额。切分的输入是请求的 token 序列与它的块表（block table）初始状态；输出是一串待搭载 chunk 记录，每条记录携带三样东西：该 chunk 在请求内的起始偏移、chunk 长度 $c_j$、以及该请求已分配的 KV 块句柄。这三样缺一不可——起始偏移决定 chunk 内因果 attention 的可见范围，块句柄决定 chunk 算出的 KV 往哪里落。</p>\n<p>入队这一步的代价常被低估。切分本身是纯 CPU 操作，但它决定了后续每一步的 batch 构成，因此队列必须维护一个可被 decode iteration 快速取用的有序结构。若队列按到达顺序 FIFO 取 chunk，先到的长 prompt 会连续占据多个 decode step 的搭载位，短 prompt 的 chunk 被推迟，长尾样本的首 token 时延被拉长；若按 chunk 长度或请求剩余长度排序，则调度器每步都要做一次小规模重排。工程上通常采用 FIFO 加一个“每请求最多连续搭载 N 个 chunk”的软约束，把单请求的搭载占用摊平。队列深度本身也是一项显存外成本：每条 chunk 记录持有块句柄引用，队列积压意味着这些块被提前占住而不能回收，队列过长会推高 KV 池的驻留压力。</p>\n<p>具体例子：一个 8192 token 的 prompt 按 512 切分得到 16 个 chunk，第 1 个 chunk 的起始偏移为 0、长度为 512，第 16 个 chunk 起始偏移 7680、长度 512。若该请求在入队时只分配到 4 个 KV 块，则前几个 chunk 可以立即搭载，后续 chunk 必须等块表扩张后才能出队——块分配与 chunk 出队是耦合的，调度器必须在出队前确认块可用，否则搭载到一半才发现无处落 KV，只能回退。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-9\">九 · 搭载批的构成：两类 workload 拼成同一 batch</h3>\n<p>每个 decode iteration 开始时，调度器做一次批拼装。输入是当前 decode 集合 $\\mathcal{D}_t$ 与待搭载队列 $\\mathcal{Q}_t$；输出是第 $t$ 步的批 $B_t$。构成规则由下式给出：</p>\n<div class=\"formula\">$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$</div>\n<p>式子的含义是：decode 侧每个请求贡献 1 个 token（自回归的单步），prefill 侧每个被选中的 chunk 贡献 $c_j$ 个 token，且 $c_j$ 不超过 chunk_size。批的总 token 数因此是 $|\\mathcal{D}_t| + \\sum_j c_j$，这个数直接决定本步的计算量与 KV 写入量。拼装的关键约束是：一个 step 只从队列取一个 chunk，还是取多个？取一个时，批内 prefill token 数被 chunk_size 封顶，decode 侧不会被过度挤压；取多个时，prefill 吞吐上升但 decode 的每步时延被拉长。多数实现取“每步一个 chunk”，把 chunk_size 当作隐式的配比旋钮。</p>\n<p>这一步的代价体现在两个方向。计算侧，批内 token 总数上升使单步前向的 FLOPs 增加，但 decode token 与 chunk token 共享同一组权重加载，权重读取的带宽开销被摊薄——这正是搭载的收益来源。显存侧，chunk token 的中间激活（attention 的 Q/K/V、MLP 的中间张量）按 $c_j$ 线性增长，而 decode token 的激活只有 1 个 token 的量级；一个 512 token 的 chunk 带来的激活峰值可能远超整个 decode 集合。因此批拼装时必须检查激活预算，而不是只看 token 数。带宽侧，chunk 的 KV 写入是一次性的大块写，decode 的 KV 写入是每步一小块，两者混在同一 step 内会让 HBM 写带宽出现尖峰。</p>\n<p>具体例子：decode 集合有 48 个请求，队列取一个 512 token 的 chunk，则本步批为 48 + 512 = 560 个 token。若把这 512 token 的 prefill 单独成批，它需要一次独立的权重加载；搭载后这次权重加载与 48 个 decode token 共用，权重带宽开销被 560 个 token 分摊而不是 512 个，摊薄比例约一成——收益不大，但每一步都发生，累积起来才是 MFU 的差别所在。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-10\">十 · 单步前向：decode 单 token 与 chunk 内因果 attention 的分工</h3>\n<p>批送入模型后，两类 token 走的是同一条前向通路，但 attention 的形态不同。decode token 做的是标准的单步自回归：它的 query 对自身历史 KV 做全量 attention，输出 1 个 token 的 logits。chunk token 做的是 chunk 内因果 attention：第 $k$ 个 chunk token 的 query 只能看到本 chunk 内位置不晚于它的 token，以及该请求此前已落表的 KV 块。这意味着 chunk 的 attention 计算是一个下三角掩码的小矩阵乘，规模由 $c_j$ 决定，而不是全序列长度。</p>\n<p>两者共享权重加载是这一机制的核心。模型每一层的权重从 HBM 读入 SM 后，同时服务 decode 的 1 个 token 与 chunk 的 $c_j$ 个 token；若分两批执行，同一组权重会被读两遍。权重读取量按层参数规模计，与 batch 内 token 数无关，因此搭载把这份固定开销摊到了更大的 token 基数上。用公式表达，单步时间近似为：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>式子的工程含义是：搭载批的时延由算力项与带宽项中较大者决定。decode 侧带宽占比高、算力占比低，chunk 侧算力占比高、带宽占比低，两者相加后两个比值被拉近，$\\max$ 的浪费变小。对应的 MFU 为 $\\text{MFU}_{\\text{piggyback}} = (F_{\\text{decode}} + F_{\\text{prefill\\_chunk}})/(T_{\\text{step}}\\cdot P_{\\text{peak}})$。代价在于：chunk 的因果 attention 在 chunk 较小时矩阵乘的 M 维过短，tensor core 的利用率下降，SM 上出现大量半空 warp；chunk 较大时 decode 侧的单步时延被 chunk 的算力项拖住，token 级时延抖动上升。</p>\n<p>具体例子：某层 attention 中，decode 的 48 个 token 各做 1 次 query 对全历史的点积，chunk 的 512 个 token 做 512×512 的下三角点积。后者的 FLOPs 远大于前者，但两者在同一组 Q/K/V 投影权重上完成，投影层的权重读取只发生一次。若把 chunk 拆成 64 token 的小块搭载，投影层被调用 8 次、权重读 8 遍，attention 的矩阵乘 M 维只有 64，tensor core 效率明显下滑——这就是 chunk 过小导致 prefill 被切碎的具体机理。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-11\">十一 · KV 落表与请求状态迁移：chunk 完成后的块表合并</h3>\n<p>chunk 前向结束后，它算出的 KV 必须并入该请求的块表，请求才从“预填中”转入 decode 集合。输入是 chunk 各层输出的 K/V 张量与调度器为该 chunk 预分配的块句柄；输出是块表内新增的条目，以及请求状态的翻转。这一步是纯显存操作：把 K/V 按块粒度写入 KV 池的对应物理块，更新块表的逻辑到物理映射，然后把该请求的已落表长度推进 $c_j$。</p>\n<p>代价集中在写带宽与块碎片。一个 512 token 的 chunk 在每层产生 512 个位置的 K/V，层数乘以头数乘以头维度就是写入总量；这批写是一次性的大块写，与 decode 侧每步 1 个 token 的细碎写形成对比。若块表按固定块大小分配，chunk 长度不是块大小的整数倍时最后一块会出现内部碎片，碎片在长 prompt 上累积会浪费 KV 池容量。工程上常把 chunk_size 取为块大小的整数倍来规避，这也是 512 这类取值的由来之一。</p>\n<p>状态迁移还有一层调度含义：请求只有在最后一个 chunk 落表后才进入 decode 集合，此前的所有 chunk 都不产生可采样的 logits。因此一个长 prompt 的首 token 时延等于其 chunk 数乘以搭载步数——若队列积压，这个乘积会变大。具体例子：8192 token 的 prompt 切 16 个 chunk，若每步搭载一个且队列中它排在第 5 位，则它的首个 chunk 要等 5 步才被搭载，全部 16 个 chunk 落表需约 16 步（假设每步一个），首 token 时延被队列位置与 chunk 数共同决定。这也是搭载机制对长尾样本不友好的根源之一：长 prompt 的首 token 时延不再由单次预填决定，而由队列排位与 chunk 切分共同决定。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-12\">十二 · 队列耗尽与批次收尾：统计回传的时点</h3>\n<p>当 decode 集合为空且待搭载队列清空时，rollout 批次结束。收尾的输入是所有请求的完整 token 序列与逐步 logprob；输出是回传训练侧的样本统计。这一步的代价不在 GPU 而在统计口径：搭载使每个 decode step 的时延不等，若按 step 计费或按固定时间窗切分样本，长尾请求会被截断或误判超时。正确的做法是按请求维度累计 token 与 logprob，而不是按 step 维度聚合，否则搭载引入的时延抖动会污染训练侧的样本分布。</p>\n<p>队列耗尽还有一种中间态值得单独处理：decode 集合缩小而队列仍有积压时，搭载失去互补对象，chunk 独占 batch，带宽利用率回落到串行预填的水平。此时调度器应停止搭载、改为连续预填多个 chunk 直到队列清空或 decode 集合重新增长，否则每个 step 都在做“有 chunk 无 decode”的低效前向。这一判断的触发条件是 $|\\mathcal{D}_t|$ 低于某个阈值，阈值与 chunk_size 和 SM 数量相关，需按部署实测确定。</p>\n<p>具体例子：一个 rollout 批次开始时队列有 200 个 chunk、decode 集合 0，此时任何搭载都无互补对象，调度器应先做连续预填把队列压到较低水位，再开始搭载；批次末尾 decode 集合逐个退出，最后几个 step 只剩 chunk，同样应切回连续预填。把这两个端点处理掉，搭载才在中间段真正发挥算力与带宽互补的作用。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-13\">十三 · 步骤间的耦合代价：chunk_size 作为全局旋钮</h3>\n<p>把上述五步串起来看，chunk_size 不是某一步的局部参数，而是同时约束切分粒度、批构成、attention 效率、KV 碎片与首 token 时延的全局旋钮。切分步希望 chunk 大以减小队列条目数与块碎片；批构成步希望 chunk 适中以免挤压 decode；前向步希望 chunk 大以抬高 tensor core 的 M 维利用率；落表步希望 chunk 是块大小整数倍；收尾步希望 chunk 小以降低长尾请求的首 token 时延。这些诉求方向不一致，固定超参只能在 prompt 长度分布稳定的前提下取折中。</p>\n<p>分布漂移时折中失效的机理很直接：若实际 prompt 长度远大于调参时的假设，chunk 数变多、队列变长，首 token 时延按 chunk 数线性上升，长尾样本被 token 级超时误杀；若实际 prompt 远短于假设，多数请求不足一个 chunk，搭载退化为普通预填，decode 侧得不到互补，MFU 回落到串行水平。工程判断是：把 chunk_size 与 prompt 长度分布的中位数挂钩，并在分布漂移超过一定幅度时重调，而不是把 512 当作跨场景常数。这一步的代价是运维复杂度——chunk_size 变更会改变块表分配模式与队列结构，不能在批次中途热切换，只能在批次边界生效。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-14\">十四 · 搭载批的边界条件与失效代价</h3>\n<p>搭载机制并非无条件成立。其收益依赖一个隐含前提：第 t 步的搭载批必须同时含有足够多的 decode token 与恰好一个 prefill chunk，使算力密集与带宽密集两类负载在同一组权重加载下互补。用批构成式表达即 $B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\ c_j\\le \\text{chunk\\_size}$，其中 $\\mathcal{D}_t$ 为 decode 集合、$\\mathcal{Q}_t$ 为待搭载队列。当 $|\\mathcal{D}_t|$ 缩小到个位数而 $\\mathcal{Q}_t$ 仍有积压时，chunk 将独占整个 batch，权重加载只服务一个 chunk，HBM 带宽利用率回落到串行 prefill 的水平，互补关系瓦解——这是该方案最典型的失效模式，且它随 rollout 批次尾部自然出现，不需要任何外部扰动。</p>\n<p>第二个边界是 chunk_size 与 prompt 长度分布的匹配。chunk 过小则 prefill 被切碎，chunk 内因果 attention 的有效计算粒度下降，单位 token 的 attention 开销上升；chunk 过大则单个 decode step 被拉长，所有在跑 decode 请求的 token 间隔被同步拖慢。用搭载 MFU 看，$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$，chunk 过大时第一项主导、step 时间被算力项锁死，decode 侧只能等待；chunk 过小时第二项主导但 chunk 内 attention 效率损失不在公式内，属于隐性代价。prompt 长度分布漂移（例如训练中期样本从短问答转为长文档）会使原调参失效，必须重新标定。</p>\n<p>第三个代价落在时延语义上。搭载使 decode step 的时延抖动增大：无 chunk 的 step 与带 chunk 的 step 交替出现，token 级超时判定容易误杀正常的长尾样本，长尾统计失真并反向影响训练侧的样本分布。工程上应把超时判定从 per-token 改为 per-request 的累计预算，或在搭载 step 上放宽阈值，否则该机制在 RL rollout 的稳定性收益会被统计噪声抵消。此外，搭载 batch 内两类 workload 必须保持数值精度一致，量化档位不匹配会直接破坏 chunk 与 decode 共享权重加载的前提。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>表现</th><th>系统代价</th></tr></thead><tbody><tr><td>decode 集合过小</td><td>chunk 独占 batch</td><td>带宽利用率回落，互补失效</td></tr><tr><td>chunk 过小</td><td>prefill 切碎</td><td>attention 效率下降</td></tr><tr><td>chunk 过大</td><td>step 被算力项锁死</td><td>decode token 间隔拉长</td></tr><tr><td>分布漂移</td><td>原 chunk_size 失配</td><td>需重新调参，期间收益衰减</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-15\">十五 · 搭载批的构成与逐项含义</h3>\n<p>核心公式给出的是第 <em>t</em> 个 decode iteration 送入模型的批的集合构成：</p>\n<div class=\"formula\">$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$</div>\n<p>逐项拆开看。$\\mathcal{D}_t$ 是第 <em>t</em> 步仍在生成的 decode 请求集合，每个元素贡献 1 个 token 的查询长度——这是 decode 的固有形态，每步只推进一个位置。$\\mathcal{Q}_t$ 是待搭载队列，每个元素是一个尚未预填完的 prompt 片段，长度为 $c_j$，上界是固定超参 chunk_size（给定事实中的锚点为 512）。批的总 token 数因此是 $|\\mathcal{D}_t|+\\sum_{j\\in\\mathcal{Q}_t}c_j$，这个量决定了本步前向的算力需求；而批的权重加载量只与模型本身有关，与批内 token 数无关——这正是搭载得以成立的物理基础：两类 workload 共享同一组权重读取，权重加载的带宽开销被摊薄到更大的有效 token 数上。</p>\n<p>公式里容易被忽略的是 $c_j\\le\\text{chunk\\_size}$ 这个约束的方向性。它不是一个等式，而是上界：队列尾部的 chunk 可能不满，例如 prompt 总长 1300 token、chunk_size 取 512 时，切分为 512+512+276 三段，最后一段只有 276。这意味着搭载批的算力负载在步与步之间并不恒定，调度器若按满 chunk 估算吞吐会系统性高估。工程上应把 $c_j$ 的实际值而非 chunk_size 代入负载模型。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-16\">十六 · 从互补到 T_step：关键一步推导</h3>\n<p>给定公式为：</p>\n<div class=\"formula\">$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>推导的关键一步在于 $T_{\\text{step}}$ 取 max 而非求和。串行执行时，prefill 阶段与 decode 阶段各自占用一段时间，总时间是两项之和：$T_{\\text{serial}}=T_{\\text{prefill}}+T_{\\text{decode}}$，其中 $T_{\\text{prefill}}\\approx F_{\\text{prefill}}/P_{\\text{peak}}$（算力受限）、$T_{\\text{decode}}\\approx B_{\\text{decode}}/BW_{\\text{HBM}}$（带宽受限）。合并到同一 step 后，算力项与带宽项在同一时间窗口内并行推进，硬件在任一时刻只被其中一个瓶颈卡住，于是时间取两者较大值。互补的收益就来自这个 max 替代 sum：当 $F_{\\text{prefill}}/P_{\\text{peak}}$ 与 $B_{\\text{decode}}/BW_{\\text{HBM}}$ 量级接近时，$T_{\\text{piggyback}}$ 约为串行时间的一半，MFU 相应接近翻倍；当两者严重失衡时，max 退化为其中较大的一项，收益衰减。</p>\n<p>把 decode 自身的算力项与带宽项也并入，更完整的写法是 $T_{\\text{step}}\\approx\\max\\big((F_{\\text{dec}}+F_{\\text{chunk}})/P_{\\text{peak}},\\ (B_{\\text{dec}}+B_{\\text{chunk}})/BW_{\\text{HBM}}\\big)$，其中 $B_{\\text{dec}}$ 主要是权重加载与 KV cache 读取，$B_{\\text{chunk}}$ 主要是该 chunk 的 KV 写入与激活读写。注意 $F_{\\text{chunk}}$ 随 $c_j$ 增长近似超线性（chunk 内因果 attention 的平方项），而 $B_{\\text{chunk}}$ 近似线性，所以 chunk 越大，算力项越容易成为 max 的支配项——这就是 chunk 过大拖慢 decode step 的定量根源，而非笼统的“负载不均”。</p>\n<p>系统代价上，这个 max 结构直接决定容量规划：给定 $P_{\\text{peak}}$ 与 $BW_{\\text{HBM}}$，可搭载的 chunk 总量上限是 $\\min\\big(P_{\\text{peak}}\\cdot T_{\\text{target}}-F_{\\text{dec}},\\ BW_{\\text{HBM}}\\cdot T_{\\text{target}}-B_{\\text{dec}}\\big)$ 反解出的 $F_{\\text{chunk}}$ 对应值。若 decode 集合本身已接近带宽饱和（长上下文、大 KV），可搭载余量趋近于零，此时继续往批里塞 chunk 只会拉长 $T_{\\text{step}}$ 而不提升 MFU。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-17\">十七 · 伪代码：从队列到块表并入</h3>\n<p>把机制落到可实现层面，主循环的形状如下（伪代码思路，非可执行代码）：</p>\n<ul>\n<li>初始化：$\\mathcal{D}\\leftarrow\\varnothing$，$\\mathcal{Q}\\leftarrow$ 按到达顺序存放的 (request_id, chunk 起始偏移, $c_j$) 三元组；块表 block_table 按请求维护。</li>\n<li>每步：若 $\\mathcal{Q}$ 非空，弹出队首元素 $j$；构造批 $B_t=\\mathcal{D}\\cup\\{j\\}$；对 $\\mathcal{D}$ 中每个请求取其最后位置的 token 作为查询，对 $j$ 取其 chunk 内全部 $c_j$ 个 token 作为查询，位置编码按各自请求的绝对偏移写入。</li>\n<li>前向：一次权重加载，decode 部分做单步因果 attention（KV 从块表按页读取），chunk 部分做 chunk 内因果 attention（chunk 内 token 互相可见，chunk 之前的历史 KV 从块表读取）。</li>\n<li>采样：仅对 $\\mathcal{D}$ 中的请求采样下一个 token 并追加 KV；对 $j$ 不采样，只把 $c_j$ 个位置的 KV 写入其请求的块表。</li>\n<li>状态迁移：若 $j$ 的 chunk 是其 prompt 的最后一段，将该请求移入 $\\mathcal{D}$；否则把剩余部分重新切分压回 $\\mathcal{Q}$ 队首或队尾（取决于是否要求同一请求的 chunk 连续搭载）。</li>\n<li>终止：$\\mathcal{D}=\\varnothing$ 且 $\\mathcal{Q}=\\varnothing$ 时结束，逐请求统计 token 数与 logprob 回传。</li>\n</ul>\n<p>实现上两个细节决定成败。其一是 attention 掩码的构造：批内 decode 查询与 chunk 查询的可见集合不同，需要一份按请求拼接的变长掩码，若用统一的最大长度掩码会浪费算力；工程上通常按“decode 段 + chunk 段”分段调用 attention kernel，避免跨段污染。其二是块表并入的原子性：chunk 的 KV 写入必须在同一步内完成并可见，否则下一步若该请求转入 decode，其首步 attention 会读到不完整的 KV。这要求块表更新与 KV 写入在同一 stream 上排序，不能异步放飞。</p>\n<p>代价侧：每步多一次队列弹出与掩码构造的 host 开销，在 decode step 本身只有数十微秒量级时不可忽略；chunk 段与 decode 段若不能共享同一个融合 kernel，会引入额外的 kernel launch 与同步，实际 $T_{\\text{step}}$ 高于 max 公式的理想值。这是公式与实现之间的固定折损，容量规划时应留出余量。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-18\">十八 · chunk_size 的定量取舍与抖动</h3>\n<p>chunk_size 是唯一显式超参，其取值直接改写公式两侧。设 prompt 长度分布为 $L$，则单请求被切成的段数为 $\\lceil L/\\text{chunk\\_size}\\rceil$，一个请求从入队到转入 decode 所跨越的 decode step 数即等于段数（假设每步搭载一个 chunk）。因此 chunk 越小，同一请求的预填被拉得越长，其首 token 的等待时间随段数线性增长；chunk 越大，段数越少但每步的 $F_{\\text{chunk}}$ 越大，$T_{\\text{step}}$ 的算力项越可能压过带宽项，decode 被拖慢。</p>\n<p>更细的一层是 attention 效率。chunk 内因果 attention 的计算量随 $c_j$ 平方增长，而 chunk 与历史 KV 的交叉 attention 随 $c_j$ 线性增长。chunk 过小时，交叉 attention 的固定开销（页表遍历、KV 分块加载）占比升高，单位 token 的有效算力下降；这就是“prefill 被切碎、attention 效率下降”的机制解释，而非经验之谈。给定事实未给出效率拐点的具体数值，工程判断应以实测的每 token 有效 FLOPs 随 chunk_size 的变化曲线来定位，而不是照搬 512 这个锚点。</p>\n<p>抖动是搭载的固有副作用。串行方案下 decode step 的时长相对平稳；搭载后，$T_{\\text{step}}$ 随每步搭载的 $c_j$ 与 $\\mathcal{D}$ 规模波动，token 级超时判定若按固定阈值执行，会把恰好搭载了大 chunk 的那几步误判为异常，误杀正常长尾样本。缓解手段是把超时判定从“单步时长”改为“请求级累计预算”，或对搭载步单独放宽阈值并在统计时标注。这属于调度器策略层，不改公式，但改公式在 SLO 约束下的可行域。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-19\">十九 · 队列积压：互补对象消失的失败模式</h3>\n<p>公式的成立隐含一个前提：$\\mathcal{D}_t$ 非空且规模足以提供带宽侧的负载。当 rollout 批次进入尾段，decode 集合逐步缩小，而 $\\mathcal{Q}$ 仍有积压时，搭载批退化为“纯 prefill chunk 批”——此时 $B_{\\text{decode}}\\approx 0$，$T_{\\text{step}}$ 的 max 由算力项独占，带宽利用率回落到与串行 prefill 相同的水平，互补收益归零。这不是参数调错，而是负载形态变化导致的机制失效。</p>\n<p>定量地看，互补有效的条件是 $F_{\\text{chunk}}/P_{\\text{peak}}\\approx B_{\\text{dec}}/BW_{\\text{HBM}}$，即两侧时间量级可比。当 $|\\mathcal{D}_t|$ 下降到使 $B_{\\text{dec}}$ 远小于 $B_{\\text{chunk}}$ 时，应主动停止搭载、改为纯 prefill 批推进队列，或反向操作：把队列中的 chunk 合并成更大的批一次预填完，用算力换时间。调度器需要一个基于当前 $\\mathcal{D}_t$ 规模与 $\\mathcal{Q}$ 积压深度的切换判据，而不是无条件每步搭载一个 chunk。</p>\n<p>另一个方向的失败是 chunk_size 与 prompt 长度分布漂移不匹配。分布变长时固定 chunk_size 使段数增多、单请求预填跨步数上升，长尾样本的首 token 延迟恶化；分布变短时 chunk 常常不满，$c_j$ 的实际值远小于上界，公式中按 chunk_size 估算的算力负载被高估，调度器误以为已接近算力饱和而减少搭载，实际带宽仍有空余。工程上应把 chunk_size 与长度分布的分位数绑定（例如按 P90 长度反推段数上限），并在分布漂移时重新标定，而不是把 512 当作常量写死。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-20\">二十 · 搭载批的边界：互补失效、抖动代价与队列积压</h3>\n<p>把搭载公式拆开看，真正决定成败的不是分子里的算力项，而是分母中那个取max的带宽项。$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$ 推导的关键一步在于：decode 侧每步只搬一组权重却只产出极少 token，其 $B_{\\text{decode}}/F_{\\text{decode}}$ 比值远高于 prefill chunk；而 prefill chunk 恰好相反。两者拼进同一 batch 后，权重加载被两类 workload 摊薄，$F$ 项与 $B$ 项同时向 $P_{\\text{peak}}$ 与 $BW_{\\text{HBM}}$ 逼近，$T_{\\text{step}}$ 由两项中的较大者钳住，MFU 才得以抬升。反过来说，只要某一侧的量不足以让两项接近，max 就退化为单侧瓶颈，搭载的收益立刻归零——这就是本方案的失效判据，而不是“利用率会变好”这种定性期望。</p>\n<p>第一个失效条件是 chunk_size 与 prompt 长度分布失配。chunk 取 512 token 时，若实际 prompt 普遍只有一两百 token，切分后每个 chunk 的因果 attention 有效长度被压得很短，prefill 的算力密度下降，$F_{\\text{prefill\\_chunk}}$ 缩水，分子补不上 decode 的带宽缺口；反之若 prompt 动辄数千 token 而 chunk 仍固定 512，单个 chunk 的 prefill 时间被拉长，$T_{\\text{step}}$ 的算力项反超带宽项，decode 请求被迫等这个 chunk 走完，token 间延迟被直接拖慢。伪代码层面这体现为一个硬编码常量：<code>for step in decode_loop: chunk = queue.pop(chunk_size); batch = decodes + [chunk]; forward(batch)</code>——chunk_size 是超参而非自适应量，prompt 长度分布漂移时必须重新调参，否则互补对象错位。系统代价是可测的：chunk 过小使 prefill 被切碎、attention 效率下降，chunk 过大使 decode step 被拖慢，两条路径都让 $T_{\\text{step}}$ 的 max 落在错误的一侧。</p>\n<p>第二个失效条件是队列与 decode 集合的比例失衡。搭载要求 $\\mathcal{Q}_t$ 非空且 $\\mathcal{D}_t$ 有足够多请求，才能让 $B_t$ 同时含两类 workload。当待搭载队列积压而 decode 集合因请求陆续完成而缩小时，chunk 找不到互补对象，prefill chunk 独占整个 batch，带宽利用率回落到串行 prefill 的水平，搭载退化为普通分块预填。规模上限正卡在这里：decode 集合过小则搭载收益下降，而 decode 集合的大小又受并发请求数与生成长度约束，单引擎同机共卡部署下无法靠扩副本缓解。工程判断是给队列设水位线，队列深度超过 decode 集合可承载的互补容量时就该暂停切分或降级为串行，而不是继续往 batch 里塞 chunk。</p>\n<p>第三个代价是时延抖动，它比吞吐损失更难处理。搭载使每个 decode step 的耗时随所挂 chunk 的长度与因果 attention 形态波动，$T_{\\text{step}}$ 不再是稳定值，token 级超时判定会把正常的长尾样本误杀，长尾统计失真并反向影响训练侧的样本分布。RL rollout 里 logprob 与 token 统计是训练信号的一部分，抖动带来的采样偏差不会被 MFU 的提升抵消。可控的做法是把 chunk 搭载位置与超时阈值解耦：对挂在 decode step 上的 chunk 单独计时，token 级超时只统计纯 decode 段，长尾样本按请求粒度而非 step 粒度归档。表格对比三种配置的边界行为：</p>\n<table class=\"mini\"><thead><tr><th>配置</th><th>互补效果</th><th>主要代价</th></tr></thead><tbody><tr><td>chunk 偏小</td><td>prefill 算力密度不足，$F$ 项补不上</td><td>attention 效率下降，切分开销上升</td></tr><tr><td>chunk 偏大</td><td>算力项反超带宽项，max 钳在算力侧</td><td>decode token 间延迟被拉长</td></tr><tr><td>队列积压、decode 缩小</td><td>互补对象消失，退化为串行 prefill</td><td>带宽利用率回落，搭载白做</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-21\">二十一 · 搭载批的边界：互补失效与抖动代价</h3>\n<p>搭载批的构成决定了这套方案的上限：$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$。互补成立的前提是 $\\mathcal{D}_t$ 与 $\\mathcal{Q}_t$ 同时非空且量级相当——decode 侧提供带宽压力，chunk 侧提供算力压力，二者共享一次权重加载。一旦 $\\mathcal{D}_t$ 收缩到只剩少数请求，搭载就失去互补对象，prefill chunk 独占 batch，HBM 带宽利用率回落到串行预填的水平，公式中的 $T_{\\text{step}}$ 退化为纯算力项，搭载收益归零。这是队列积压与 decode 集合缩小同时发生时的典型失效。</p>\n<p>第二个边界在 chunk_size 与 prompt 长度分布的匹配。chunk 过小，prefill 被切碎，chunk 内因果 attention 的有效计算密度下降，固定开销摊薄不掉；chunk 过大，单个 step 的算力项压过带宽项，decode 请求被迫等待同一 step 完成，decode 的 token 间延迟被拉长。分布漂移时固定超参必须重调，否则两类瓶颈的互补关系直接失效。下表给出两种失配的代价落点：</p>\n<table class=\"mini\"><thead><tr><th>失配方向</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>chunk 过小</td><td>prefill 切碎，attention 效率下降</td><td>算力项填不满，$T_{\\text{step}}$ 中带宽项主导，chunk 推进变慢</td></tr><tr><td>chunk 过大</td><td>decode 被拖慢，step 内 decode token 等待</td><td>decode 时延抖动增大，token 级超时误判上升</td></tr></tbody></table>\n<p>第三个代价是时延抖动本身。搭载使每个 decode step 的时长不再由 decode 集合单独决定，而由当步搭载的 chunk 长度与数量共同决定，$T_{\\text{step}}$ 的方差显著高于纯 decode。对 rollout 的 token 级超时判定而言，这意味着正常的长尾样本会被误杀，长尾统计失真并反向影响训练侧的样本分布。工程上的判断是：把超时判定从单 step 改为按请求累计 token 时间窗，或在队列积压时主动降低搭载频率，用吞吐换时延稳定性——这套方案不改变样本集合，只提升单引擎利用率，因此稳定性策略必须外挂在调度器上，而不是塞进模型执行路径。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-22\">二十二 · 请求形态：什么样的 rollout 批次才喂得饱搭载</h3>\n<p>搭载解码的收益来自一个结构性事实：同一 step 内，decode 侧吃 HBM 带宽、prefill 侧吃 SM 算力，两类瓶颈在时间上重叠才能互相填坑。因此它偏好的请求形态不是“任意混合”，而是<strong>长短 prompt 同时在场、且长 prompt 持续有新到达</strong>的 rollout 批次。典型场景是 RL 训练侧刚下发一批新样本：一部分样本 prompt 很短、几乎立刻进入 decode；另一部分样本 prompt 很长，需要被切成多个 chunk 排队。此时 decode 集合 <em>D<sub>t</sub></em> 非空、待搭载队列 <em>Q<sub>t</sub></em> 也非空，搭载批才成立。</p>\n<p>反过来，若一个 rollout 批次里所有 prompt 长度接近，无论全短还是全长，搭载都退化成“单类 workload 独占 step”：全短时队列很快清空，后续 step 只剩 decode，带宽利用率回落；全长时 decode 集合长期为空，每个 step 都是纯 prefill，算力密集但带宽闲置。长度分布的<strong>方差</strong>而非均值，才是这个算法真正的负载前提。</p>\n<p>具体例子：一个 GRPO 式 rollout 批次里，若 80% 样本 prompt 长度集中在同一区间、20% 是长尾长 prompt，那么搭载窗口只存在于长尾样本被切块消费的那段时间；一旦长尾样本全部转入 decode，搭载收益即消失。调度器需要按“长尾样本到达节奏”而不是“平均长度”来判断是否启用搭载。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-23\">二十三 · 长度分布与 chunk_size 的匹配关系</h3>\n<p>chunk_size 是固定超参，事实给出的锚点是 512 token。它与 prompt 长度分布之间存在一个可推导的匹配条件。设待搭载队列中第 <em>j</em> 个请求的 prompt 长度为 <em>L<sub>j</sub></em>，则它被切成的 chunk 数约为 ⌈<em>L<sub>j</sub></em>/chunk_size⌉；这些 chunk 要在 decode 集合存续期间被逐个消费掉，才能保证互补不中断。于是有粗略的负载配方约束：</p>\n<div class=\"formula\">$$\\frac{\\sum_j \\lceil L_j/\\text{chunk\\_size}\\rceil}{\\bar{D}}\\ \\lesssim\\ \\text{可搭载 step 数}$$</div>\n<p>其中 <em>D̄</em> 是 decode 集合的平均规模。左端是“总 chunk 供给”，右端是“decode 侧能提供的搭载槽位”。左端远大于右端，说明 chunk 供给过剩、队列积压；左端远小于右端，说明搭载槽位空转、互补对象不足。这个比值是调 chunk_size 的第一性依据，而不是拍脑袋取 512。</p>\n<p>代价体现在两端：chunk 过小（远小于 512）时，prefill 被切碎，chunk 内因果 attention 的有效计算长度变短，attention 效率下降，单位 token 的算力开销上升；chunk 过大时，单个 step 里 prefill 部分占比过高，decode token 的推进被拖慢，decode 侧时延被拉长。两种失配都会让 <em>T<sub>step</sub></em> 的 max 项从“算力/带宽互补”退化为“单侧主导”，MFU 回落。</p>\n<p>工程判断：chunk_size 应按 prompt 长度分布的<strong>分位数</strong>选，而不是按均值。若长尾 prompt 长度普遍是 chunk_size 的若干倍，切块数过多会放大队列积压；若长尾长度只略大于 chunk_size，则切块收益本就有限，搭载的价值主要体现在“不让长 prompt 阻塞短 prompt 的 decode”。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-24\">二十四 · 并发与批大小：decode 集合规模决定收益上限</h3>\n<p>搭载批的构成由 <em>B<sub>t</sub></em> = decode 集合 ∪ 一个 chunk 决定。decode 集合规模 <em>|D<sub>t</sub>|</em> 直接决定这个 batch 的“带宽底噪”：decode 侧每 step 要读全部在跑请求的 KV 与权重，规模越大，单位 step 的带宽占用越高，留给 prefill chunk 的算力互补空间反而被压缩——因为 <em>T<sub>step</sub></em> 的 max 项可能被带宽项锁死。规模上限受 chunk_size 与 decode 集合规模共同约束，事实未给出具体数值，但方向明确：decode 集合过小，搭载收益下降；过大，则互补失效。</p>\n<p>并发配方因此是双向的：一方面要保证 decode 集合始终有足够多的在跑请求，让每个 step 都有带宽密集的底料；另一方面不能让 decode 集合膨胀到带宽项主导 <em>T<sub>step</sub></em>，否则 chunk 搭载进来也只是排队等带宽。伪代码思路是调度器在每个 iteration 先估算当前 decode 集合的带宽需求 <em>B<sub>decode</sub></em>，再决定本 step 是否搭载 chunk、以及搭载多长的 chunk：</p>\n<div class=\"formula\">$$\\text{搭载条件：}\\ \\frac{B_{\\text{decode}}}{BW_{\\text{HBM}}} &lt; \\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}}$$</div>\n<p>即只有当带宽项尚未成为 <em>T<sub>step</sub></em> 的瓶颈时，塞入 chunk 才真正提升 MFU；否则搭载只是把算力空转换成了队列等待。这是并发调度的核心判据，也是“批大小”与“chunk_size”必须联合调参的原因。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-25\">二十五 · 负载不对时的三种失效形态</h3>\n<p>失效一：<strong>队列积压而 decode 集合萎缩</strong>。当长 prompt 到达速率高于 decode 侧消费速率，待搭载队列越堆越长，而 decode 集合因请求陆续完成而缩小。此时 chunk 找不到互补对象，prefill chunk 独占 batch，带宽利用率回落到纯 prefill 水平，搭载退化为串行 prefill。表现为 step 时延先升后稳、MFU 掉回基线。</p>\n<p>失效二：<strong>时延抖动误杀长尾样本</strong>。搭载使 decode step 的时延抖动增大——含 chunk 的 step 比纯 decode step 慢。若 rollout 侧设有 token 级超时判定，抖动会把正常的长尾样本误判为超时并丢弃，长尾统计失真，进而改变训练侧看到的样本分布。这不是性能问题而是<strong>正确性问题</strong>：被误杀的往往正是长 prompt 样本，而它们恰是搭载机制最该服务的对象。</p>\n<p>失效三：<strong>长度分布漂移后 chunk_size 失配</strong>。chunk_size 是固定超参，prompt 长度分布随训练阶段漂移（例如课程学习推进、任务难度上升导致 prompt 变长），原 chunk_size 不再匹配，切块数暴增或切块收益消失，算力与带宽互补失效。事实明确指出：分布漂移时需重新调参，否则互补失效。</p>\n<p>三种失效的共同特征是 <em>T<sub>step</sub></em> 的 max 项被单侧锁死，互补结构瓦解。工程上应把“搭载 step 占比”“队列长度/ decode 集合规模比”“含 chunk step 与纯 decode step 的时延比”作为三个在线监控量，任一越界即触发 chunk_size 重调或暂停搭载。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-26\">二十六 · 与相邻机制的负载分工</h3>\n<p>负载配方还要回答“什么时候不该用搭载”。与 Rollout 前缀 KV 共享消除同 prompt 重复预填不同，搭载是在时间维度把不同 prompt 的 prefill chunk 塞进 decode step；当前缀共享已经把重复预填压到很低时，待搭载队列的 chunk 供给本就稀少，搭载的互补对象不足，收益自然下降。与在线 Rollout 剪枝放弃低价值轨迹不同，搭载不改变样本集合、只提升单引擎利用率，因此它无法解决“样本本身太多”的负载问题——那是剪枝的职责。</p>\n<p>具体例子：一个同机共卡的 RL 训练与 rollout 场景，若前缀共享命中率高、长 prompt 大多共享前缀，则真正需要预填的新 token 少，chunk 队列短，搭载窗口窄；此时应把 chunk_size 调小以维持每个 step 都有可搭载的 chunk，而不是沿用 512。反之若前缀共享命中率低、长 prompt 多为全新内容，chunk 供给充足，chunk_size 可放大以减少切块开销。</p>\n<p>负载配方的最终判断落在一条工程准则上：搭载解码的适用域是“长短混合、训练与 rollout 同机共卡、decode 集合与 chunk 队列同时非空”的批次；一旦这个交集消失，就该退回纯 decode 或纯 prefill 调度，而不是硬把 chunk 塞进空转的 batch。chunk_size 与并发规模的联合调参，本质是在维持这个交集的存在时间。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-27\">二十七 · 负载配方：互补窗口的边界与失效条件</h3>\n<p>搭载机制能成立，靠的是一个隐含的负载前提：在任意一个decode step上，待搭载队列里始终有chunk可搭，同时在跑的decode集合足够大，使两类workload在同一个batch内形成互补。这个前提等价于一个“互补窗口”条件——设第t步decode集合规模为|D_t|、待搭载队列积压为|Q_t|，则只有当两者同时非空且量级可比时，搭载批才真正填满SM与HBM带宽。请求形态因此被约束得很窄：长短prompt混合、且长prompt持续到达的rollout批次。若prompt长度分布集中在短端，切出的chunk数量少、队列很快清空，搭载退化为普通decode，prefill只能串行补做；若集中在长端而decode集合很小（例如批次末尾只剩少数长尾请求在跑），chunk独占batch，带宽利用率回落到纯prefill水平。这就是队列积压而decode集合缩小时的失效路径：互补对象消失，公式中的$B_{\\text{prefill\\_chunk}}$项独自占满HBM带宽，而算力侧因batch内没有decode token而闲置。</p>\n<p>chunk_size是固定超参，它与prompt长度分布的匹配程度直接决定互补是否有效。用搭载批的构成式可看出调参的两个方向：</p>\n<div class=\"formula\">$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$</div>\n<p>chunk过小（远小于512 token量级）时，prefill被切碎成大量短片段，chunk内因果attention的算术强度下降，权重加载次数相对token数上升，prefill侧从算力密集滑向带宽密集——两类workload同质化，互补失效，同时队列管理开销与块表合并频次上升。chunk过大时，单个chunk在step内的算力占比压过decode，$T_{\\text{step}}$被prefill项主导，decode请求的token间延迟被拉长，连续批处理的公平性受损。工程判断是：chunk_size应取到使单step内prefill chunk的FLOPs与decode batch的FLOPs大致同量级，且chunk的HBM流量不超过decode流量的一个可控倍数；prompt长度分布漂移（例如训练阶段切换、任务难度变化导致生成长度整体上移）后必须重新标定，否则互补窗口错位。</p>\n<p>代价首先体现在时延抖动上。搭载使每个decode step的$T_{\\text{step}}$不再由decode自身决定，而由$\\max(\\cdot)$中较大的那一项决定；chunk长度在$c_j\\le\\text{chunk\\_size}$内可变，于是step时延呈现与chunk边界同步的周期性抖动。对rollout的token级超时判定而言，这是实质性风险：以固定token间隔判超时的逻辑会把搭载step上的正常长尾样本误杀，长尾统计失真，进而改变回传训练侧的样本分布——这不是性能问题而是样本质量问题。其次是规模上限：收益随decode集合规模增长而增长，decode集合过小则搭载收益下降，具体上限未给出，但可由互补条件定性判断——当|D_t|小到其HBM流量不足以吸收一个chunk的算力时，搭载只剩拖慢decode的副作用。部署上该机制单引擎同机共卡即可，无需prefill/decode分离，但要求搭载batch内两类workload数值精度一致，量化档位未给出时须在引擎侧统一，避免同一batch内混合精度路径造成额外转换开销。它与前缀KV共享、在线剪枝的差别在于：不改变样本集合、不消除重复预填，只在时间维度上做workload拼装，因此负载配方一旦偏离混合长短prompt形态，它没有任何兜底手段。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>互补是否成立</th><th>主要代价</th></tr></thead><tbody><tr><td>长短prompt混合、长prompt持续到达</td><td>成立，SM与HBM同时被填满</td><td>step时延周期性抖动</td></tr><tr><td>prompt普遍偏短、队列快速清空</td><td>退化，搭载机会稀少</td><td>prefill串行补做，利用率回落</td></tr><tr><td>decode集合缩小、队列积压</td><td>失效，chunk独占batch</td><td>带宽利用率回落、算力闲置</td></tr><tr><td>chunk_size与长度分布错配</td><td>失效，两类workload同质化或被拖慢</td><td>需重新调参，抖动加剧</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-28\">二十八 · 负载配方：互补成立的前提与失效边界</h3>\n<p>搭载解码的收益不是无条件成立的，它本质上是把两条瓶颈曲线叠在同一 step 上，让 <span class=\"formula-inline\">$$T_{\\text{step}}$$</span> 由算力项与带宽项的较大者决定。当 <span class=\"formula-inline\">$$F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}$$</span> 与 <span class=\"formula-inline\">$$B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}$$</span> 之比接近 <span class=\"formula-inline\">$$P_{\\text{peak}}/BW_{\\text{HBM}}$$</span> 时，两项同时被填满，MFU 最高；一旦某一侧压倒另一侧，搭载就退化为串行执行的低效版本。因此负载配方的核心是让 decode 集合与待搭载队列在体量上大致匹配：decode 侧提供足够的带宽压力，prefill chunk 侧提供足够的算力压力，二者缺一不可。</p>\n<p>适合的请求形态是长短 prompt 混合的 rollout 批次——短 prompt 快速转入 decode 集合持续供压，长 prompt 被切成 512 token 的 chunk 排队搭载。若批次内 prompt 长度高度同质（全短或全长），互补对象就会缺失：全短时队列迅速清空，搭载无以为继；全长时 decode 集合长期偏小，chunk 独占 batch，带宽利用率回落。长度分布漂移还会让固定的 chunk_size 失配，过小则 prefill 被切碎、chunk 内因果 attention 效率下降，过大则单个 decode step 被拖长，两类瓶颈互补失效。</p>\n<p>并发与批大小的约束体现在 decode 集合规模上：集合过小，搭载收益随互补对象减少而衰减，规模上限受 chunk_size 与 decode 集合规模共同约束。更隐蔽的代价是时延抖动——搭载使每个 decode step 的耗时随 chunk 长度波动，token 级超时判定容易误杀正常长尾样本，长尾统计失真后回传训练侧的样本分布随之偏移。工程判断是：先按 prompt 长度分布定 chunk_size，再以 decode 集合规模为搭载开关，队列积压而 decode 集合缩小时主动暂停搭载，避免 chunk 独占 batch 的退化。</p>\n<table class=\"mini\"><thead><tr><th>负载状态</th><th>互补效果</th><th>系统代价</th></tr></thead><tbody><tr><td>长短混合、decode 集合充足</td><td>算力与带宽同填，MFU 高</td><td>step 时延抖动增大</td></tr><tr><td>prompt 同质、队列空或 decode 集合小</td><td>互补失效，退化为串行</td><td>带宽或算力闲置</td></tr><tr><td>chunk_size 与分布失配</td><td>attention 效率下降或 decode 被拖慢</td><td>长尾超时误杀、统计失真</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-29\">二十九 · 硬件档位：先定“谁和谁同卡”，再定卡型</h3>\n<p>搭载式分块预填的部署第一决策不是选 B200 还是 B300，而是确定 rollout 引擎与训练侧是否同机共卡。该机制的全部收益来自“同一 step 内算力密集与带宽密集互补”，一旦 rollout 引擎被拆到独立节点，搭载批仍然成立，但跨节点权重同步与 KV 回传会把收益吃掉。工程上按三档划分：同卡同进程（rollout 与训练共享 GPU，靠时分复用）、同机异卡（同节点内不同 GPU，NVLink 域内传 KV）、异机（跨节点，走 RDMA/NIXL）。只有前两档能完整保留搭载的互补性；第三档应直接改用分离式预填/解码拓扑，把 chunk 搭载降级为引擎内部的批构成技巧。</p>\n<p>卡型选择由搭载批的两类工作负载共同决定。decode 侧受 HBM 带宽约束，prefill chunk 侧受 SM 算力与 tcgen05 MMA 吞吐约束，因此单卡需要同时具备高带宽与高 Tensor Core 吞吐——B200/B300 这一档满足，而带宽/算力比失衡的卡会让搭载批的瓶颈项固定在公式中的某一项，互补失效。GB200/GB300 NVL72 机柜档的价值在于把 decode 集合规模做大：搭载收益随 decode 集合增大而上升，因为 chunk 需要足够多的 decode 请求作为“带宽填充物”。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>这个 max 结构直接给出档位判断：若实测 T_step 长期由第一项决定，说明算力是短板，应减少 chunk 搭载量或换更高 P_peak 的卡；若由第二项决定，说明带宽是短板，应扩大 decode 集合或提高 chunk 占比。代价上，同卡同进程档位会引入训练与 rollout 的显存争抢，KV cache 可用容量被压缩，直接限制 decode 集合规模，进而削弱搭载的互补对象。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-30\">三十 · 并行拓扑：TP 与 EP 的取舍由 chunk 的 attention 形态决定</h3>\n<p>搭载批里，decode token 做单步前向，chunk token 做 chunk 内因果 attention，两者共享同一组权重加载。这意味着权重的切分方式必须同时适配两种计算形态。TP 把每层权重按 hidden 维切开，decode 与 chunk 都受益于单卡权重驻留减少、权重加载摊薄；但 TP 度增大后每卡分到的 token 数下降，chunk 内因果 attention 的并行度被切碎，attention 效率下降。EP 则把 MoE 专家分布到多卡，chunk 的长序列在专家并行下需要 all-to-all，搭载批的时延抖动被通信放大。</p>\n<p>可复现的拓扑思路：以单机 8 卡为基本单元，TP=8 覆盖稠密层，MoE 层用 EP 跨同一 NVLink 域；decode 集合与 chunk 队列共享同一 TP 组，不额外开子组，避免 chunk 与 decode 走不同集合通信路径造成 step 内两次同步。若模型为纯稠密，TP 度按“单卡权重 + KV 块表可容纳的最大 decode 集合”反推，而不是按训练时的 TP 度照搬。工程代价体现在通信量：TP 每层两次 all-reduce，搭载批把 prefill chunk 的激活也纳入同一次 all-reduce，通信量与 (decode token 数 + chunk token 数) 成正比，chunk_size 越大，单 step 通信越重。</p>\n<ul>\n<li>机制约束：chunk 与 decode 必须处于同一 TP/EP 组，否则权重加载无法共享，搭载失去意义。</li>\n<li>代价：TP 度上升降低单卡 token 密度，chunk 内 attention 的 tile 利用率下降。</li>\n<li>例子：8 卡 TP=8 部署稠密模型，decode 集合 64 请求、chunk_size=512，单 step 内 chunk token 占 batch token 的多数，all-reduce 消息尺寸由 chunk 主导。</li>\n</ul>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-31\">三十一 · 量化方案：搭载批内两类 workload 必须同精度</h3>\n<p>部署配方明确要求“保证搭载 batch 内两类 workload 的数值精度一致”。原因在数值路径：decode token 与 chunk token 拼成同一 batch 送入模型，若 decode 走 FP8 而 chunk 走 NVFP4，同一层权重需要两套 scale 与两套反量化路径，权重加载不再共享，搭载的核心机制被破坏；更糟的是 chunk 的 KV 块写入块表后，该请求转入 decode 集合，若精度档位在转入时切换，KV 的量化 scale 需要重算，块表一致性被打破。</p>\n<p>因此量化档位是全局单档：整条 rollout 引擎统一 NVFP4 或统一 FP8，不允许按请求类型分档。NVFP4 的优势在权重与 KV 的显存占用，直接放大 decode 集合规模上限，从而增强搭载的互补对象；代价是 chunk 内因果 attention 的数值稳定性需要额外处理（该主题在 NVFP4 量化 Rollout 稳定化条目展开，此处只作指路）。FP8 的数值余量更大，适合 chunk 较长、attention 累加链更长的配置。选择判据是 chunk_size：chunk 越长，单 chunk 内累加越长，越倾向 FP8；chunk 越短，越能承受 NVFP4 的激进档位。</p>\n<table class=\"mini\"><thead><tr><th>量化档位</th><th>对搭载的影响</th><th>主要代价</th></tr></thead><tbody><tr><td>统一 NVFP4</td><td>KV 与权重占用下降，decode 集合可扩大，互补对象增多</td><td>chunk 内长累加的数值风险，需稳定化处理</td></tr><tr><td>统一 FP8</td><td>数值余量大，支持更长 chunk</td><td>显存占用高于 NVFP4，decode 集合上限更低</td></tr><tr><td>混合档位</td><td>破坏权重加载共享，搭载机制失效</td><td>两套反量化路径，step 时延上升</td></tr></tbody></table>\n<p>量化还影响 T_step 的瓶颈项：低精度提升 P_peak 的有效吞吐，使公式第一项变小，瓶颈更容易落到带宽项，此时应同步扩大 decode 集合，否则搭载批的算力侧出现闲置。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-32\">三十二 · KV 策略：块表合并时机与分页粒度</h3>\n<p>chunk 执行完后其 KV 块并入对应请求的块表，该请求转入 decode 集合。这个“并入”是部署配方里最容易被低估的一步：它决定了块表的分配粒度与碎片形态。可复现的做法是让 chunk 的 KV 写入直接按 decode 阶段的分页粒度分配，即 chunk 内每 chunk_size 个 token 对应整数个 KV 页，避免 chunk 结束时做一次重排或拷贝。若 chunk_size 与页大小不成整数倍，chunk 尾部会产生半页碎片，随 chunk 数量累积，块表利用率下降，等价于压缩了 decode 集合的可用容量。</p>\n<p>KV 策略还需处理搭载批的瞬时峰值：同一 step 内既有 decode 请求追加 KV，又有 chunk 写入新 KV，块表分配器在单 step 内承受双份分配压力。配方上应预留一块专供 chunk 使用的 KV 池，与 decode 的 KV 池逻辑隔离但物理同池，chunk 结束后按页迁移到请求块表；迁移只改页表指针，不搬数据。代价是页表管理的元数据开销随 decode 集合与 chunk 队列长度线性增长，在 decode 集合很大时成为调度器的 CPU 侧瓶颈。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{peak}} \\approx \\sum_{i\\in\\mathcal{D}_t} L_i + \\sum_{j\\in\\mathcal{Q}_t} c_j$$</div>\n<p>该式给出容量规划的直观判据：搭载批的 KV 峰值等于 decode 集合已有长度加上待搭载 chunk 长度之和。chunk_size 越大，峰值越高，decode 集合可容纳的请求数越少，二者在固定显存下直接互斥。例子：统一 NVFP4 下 KV 占用减半，可把 chunk_size 从 512 提到更大档位而保持 decode 集合不变，但需重新验证 chunk 内 attention 效率。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-33\">三十三 · 调度参数：chunk_size 与 decode 集合规模的联动调参</h3>\n<p>调度参数只有两个自由度真正决定搭载成败：chunk_size 与 decode 集合规模。chunk_size 是固定超参，过小则 prefill 被切碎、attention 效率下降，过大则 decode 被拖慢；decode 集合过小则搭载失去互补对象，prefill chunk 独占 batch 导致带宽利用率回落。可复现的调参流程是：先按 prompt 长度分布定 chunk_size 的候选档（512 为基准锚点），再按显存与 KV 峰值反推 decode 集合下限，最后用 T_step 的瓶颈项归属做闭环校验。</p>\n<ul>\n<li>机制：调度器每个 decode iteration 从待搭载队列取一个 chunk，与当前所有在跑 decode 请求拼成同一 batch；队列空或 decode 集合空时搭载停止。</li>\n<li>伪代码思路：while 队列非空 and decode 集合非空: batch = decode ∪ pop(队列, chunk_size); step(batch); 若 chunk 完成则并入块表并转入 decode 集合。</li>\n<li>代价：搭载使 decode step 时延抖动增大，token 级超时判定会误杀正常长尾样本，长尾统计失真并影响训练侧样本分布。</li>\n<li>例子：prompt 长度分布漂移（长 prompt 占比上升）后，固定 chunk_size 使队列积压、decode 集合相对缩小，互补对象不足，需按新分布重调 chunk_size 与 decode 集合下限。</li>\n</ul>\n<p>调度参数还应包含一个保护项：当待搭载队列积压而 decode 集合缩小时，主动暂停搭载、让 chunk 独占 batch 跑完，避免“半搭载”状态下两类瓶颈都不满。这个保护项的触发阈值由队列长度与 decode 集合规模之比决定，是配方里唯一需要在线监控的调度量。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-34\">三十四 · 可复现配置思路：从瓶颈项反推，而不是从参数表照抄</h3>\n<p>把上述五档串成一条可复现路径：第一步，确定部署档位为同机共卡，rollout 引擎与训练侧共享 GPU 或同节点异卡，排除异机档；第二步，按模型类型定并行拓扑，稠密层 TP 覆盖单机 NVLink 域，MoE 层 EP 同域，chunk 与 decode 不分子组；第三步，量化全局单档，按 chunk_size 候选在 NVFP4 与 FP8 间二选一，禁止混合；第四步，KV 分页粒度与 chunk_size 对齐，预留 chunk 专用池并按页表指针迁移；第五步，按显存反推 decode 集合下限，按 prompt 长度分布定 chunk_size，再用 T_step 瓶颈项归属校验。</p>\n<p>校验环节是这套配方的核心：实测 MFU_piggyback 与 T_step 的两项分解，若瓶颈长期落在算力项，说明 chunk 占比过高或 decode 集合过小，应下调 chunk_size 或扩大 decode 集合；若长期落在带宽项，说明 chunk 供给不足，应上调 chunk_size 或增加待搭载队列深度。这个闭环把“调参”从经验变成可测量的工程判断，也是搭载机制在 prompt 长度分布漂移时唯一可靠的重新定档依据。</p>\n<div class=\"formula\">$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}}$$</div>\n<p>最后落在具体机制上：部署配方的稳定性不取决于单点参数，而取决于 chunk 并入块表的时机与调度器对“队列—decode 集合”比例的响应。把这两处做成显式可观测的量，搭载式分块预填才能在长 prompt 分布漂移时保持算力与带宽的互补，而不是退化成串行 prefill/decode 的低 MFU 形态。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-35\">三十五 · 搭载配方的边界：互补失效的三种工况与代价核算</h3>\n<p>这套配方的前提是“同一 step 内两类瓶颈互补”，因此它的失效条件不是单点故障，而是互补关系被打破。第一种工况是待搭载队列积压而 decode 集合萎缩：当批次内长 prompt 陆续进入收尾、decode 请求数下降，chunk 找不到足够的带宽密集对象来填 SM 之外的 HBM 带宽空档，搭载批退化为“prefill chunk 独占 batch”，带宽利用率回落到串行 prefill 的水平，收益归零。第二种是 chunk_size 与 prompt 长度分布漂移不匹配——chunk 过小则 prefill 被切碎、chunk 内因果 attention 的有效算力密度下降；chunk 过大则每个 decode step 被单个 chunk 拖长，decode 侧时延抖动放大。第三种是数值精度档位不一致：搭载 batch 内 decode token 与 chunk token 共享同一组权重加载，若两者走不同量化路径（例如 decode 用低比特权重、prefill chunk 走更高精度激活），同一 kernel 内无法复用同一份权重布局，权重加载被拆成两次，互补的前提直接消失。因此配方必须保证搭载 batch 内两类 workload 的数值精度一致，量化档位在部署时锁定为同一档，而不是按阶段分别配置。</p>\n<p>代价可以用搭载步的 roofline 形式核算，判断当前配置究竟卡在算力还是带宽：</p>\n<div class=\"formula\">$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>该式给出两个工程判断：其一，只有当 $T_{\\text{step}}$ 由算力项与带宽项中较大者决定、且两项量级接近时，搭载才真正把空闲资源吃满；若 chunk 过大使算力项远超带宽项，decode 侧就被迫等待，抖动成本转嫁到 token 级超时判定上。其二，MFU 的分母是整步时间，因此 chunk 切碎带来的 attention 效率损失会直接压低分子中的有效算力，而不是被掩盖。以一个 512 token 的 chunk 为例：若 decode 集合只剩个位数请求，带宽项由 chunk 的权重与 KV 读取主导，算力项却因 chunk 内因果 attention 的短序列而偏低，此时把 chunk_size 调大反而更划算；反之 decode 集合有数十条在跑请求时，512 的切分能让两类项贴近，互补成立。调度参数上，chunk_size 必须按 prompt 长度分布定档并在分布漂移时重调，同时给 token 级超时留出抖动余量——搭载使 decode step 时延抖动增大，超时阈值若按串行 decode 的稳态时延设定，会误杀正常长尾样本，使长尾统计失真并污染训练侧样本分布。</p>\n<table class=\"mini\"><thead><tr><th>工况</th><th>互补关系</th><th>主要代价</th><th>配方动作</th></tr></thead><tbody><tr><td>队列积压、decode 集合缩小</td><td>失效，chunk 独占 batch</td><td>带宽利用率回落</td><td>暂停搭载或合并 chunk</td></tr><tr><td>chunk 过小</td><td>部分失效</td><td>attention 效率下降</td><td>按长度分布上调 chunk_size</td></tr><tr><td>chunk 过大</td><td>部分失效</td><td>decode step 拖慢、抖动</td><td>下调 chunk_size 并放宽超时</td></tr><tr><td>精度档位不一致</td><td>失效，权重加载拆分</td><td>额外权重带宽</td><td>锁定同一量化档</td></tr></tbody></table>\n<p>规模上限同样由配方决定：收益随 decode 集合规模上升而上升，decode 集合过小则搭载失去互补对象，因此单引擎同机共卡部署时应把 decode 并发下限作为扩容判据，而不是只看队列长度。量化方案与 KV 策略在此不引入新档位，只要求搭载 batch 内权重加载路径唯一、KV 块表在 chunk 执行完后按块并入请求块表且不触发重排——块表重排会把 chunk 的 KV 写入变成跨 step 的额外拷贝，抵消掉共享权重加载省下的带宽。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-36\">三十六 · 搭载批的显存账：谁在占，谁在等</h3>\n<p>分块预填搭载解码在显存上的第一笔代价，来自“同一 step 内两类 workload 共存”这件事本身。decode 集合 $\\mathcal{D}_t$ 里每个请求都持有一份持续增长的 KV 块表，而待搭载队列 $\\mathcal{Q}_t$ 里的 chunk 在进入模型前必须先分配激活与 chunk 内因果 attention 所需的临时 KV 区，执行完才并入请求块表。这意味着在搭载 step 的峰值时刻，显存里同时存在三份东西：decode 侧的历史 KV、chunk 侧的临时 KV、以及共享权重加载所需的激活缓冲。串行 prefill/decode 时这三份是错峰的，搭载把它们压到同一个时间点上。</p>\n<p>用分页管理的语言写出来，搭载 step 的显存需求近似为：</p>\n<div class=\"formula\">$$M_{\\text{step}} \\approx \\underbrace{\\sum_{i\\in\\mathcal{D}_t} L_i \\cdot k}_{\\text{decode KV}} + \\underbrace{\\sum_{j\\in\\mathcal{Q}_t} c_j \\cdot k}_{\\text{chunk 临时 KV}} + \\underbrace{A_{\\text{batch}}}_{\\text{激活}} + W$$</div>\n<p>其中 $L_i$ 是 decode 请求当前上下文长度，$k$ 是每 token 每层 KV 字节数，$c_j\\le\\text{chunk\\_size}$，$W$ 为权重常驻。真正要盯的是第二项与第一项的比例：当 decode 集合的平均上下文已经很长（RL rollout 里长轨迹回传阶段常见），第一项主导，chunk 临时 KV 只是零头；反之在批次刚起步、decode 集合还很短时，chunk 临时 KV 会短暂压过 decode KV，成为分页分配器的主要压力源。工程判断是：分页池的预留水位必须按“decode KV 峰值 + 一个 chunk_size 的临时额度”来定，而不是按稳态 decode KV 定，否则搭载 step 会在批次前段触发分配失败回退。</p>\n<p>具体例子：chunk_size 取 512，待搭载队列里同时挂着若干条长 prompt 切出的 chunk，每个 chunk 的临时 KV 是 512 token 的量级；若 decode 集合此刻只有少量短请求，临时 KV 就是显存占用的主项。此时若把 chunk_size 调大以“提高 prefill 效率”，临时额度同比放大，分配器水位被顶穿的概率上升——这是 chunk_size 在显存维度上的隐性上限，与它在 attention 效率维度上的上限不是同一个约束。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-37\">三十七 · 带宽与算力的互补率：MFU 公式里的第二项什么时候咬人</h3>\n<p>搭载的收益全部来自 $T_{\\text{step}}$ 取 max 的那两项靠拢。前文已给出该式，这里只看它在规模上去之后的行为：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>互补成立的前提是两项量级接近。decode 侧每 step 的算力需求随 batch 内 token 数线性走，带宽需求随“权重加载 + KV 读取”走；prefill chunk 侧算力随 $c_j^2$ 的 attention 项走，带宽随 $c_j$ 的权重与 KV 写入走。当 decode 集合规模 $|\\mathcal{D}_t|$ 增大，$F_{\\text{decode}}$ 与 $B_{\\text{decode}}$ 同步上涨，但 $F_{\\text{decode}}$ 涨得更快（decode 的算术强度随 batch 提升而改善），于是 max 的第一项逐渐主导，$T_{\\text{step}}$ 变成算力受限，chunk 搭载进来的那点带宽互补价值被稀释。反过来，$|\\mathcal{D}_t|$ 很小时第一项远小于第二项，$T_{\\text{step}}$ 被 HBM 带宽钉死，chunk 的算力贡献无处安放，互补同样失效。</p>\n<p>所以搭载有一个“互补窗口”：decode 集合规模既不能太小（否则带宽项独大、chunk 算力闲置），也不能太大（否则算力项独大、chunk 带宽贡献被淹没）。这个窗口的位置由 $P_{\\text{peak}}/BW_{\\text{HBM}}$ 的比值和 chunk_size 共同决定，是部署时必须实测标定的量，而不是靠公式直接读出来的。规模上去以后第一个崩的地方往往就在这里：decode 集合被连续批处理喂到很大，$T_{\\text{step}}$ 早已算力受限，调度器却还在按“搭载能提升 MFU”的旧直觉往每个 step 塞 chunk，结果是 chunk 挤占了本可以留给 decode 的算力配额，decode 的 token 间延迟（ITL）被拉长，吞吐不升反降。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-38\">三十八 · 权重加载的共享边界与 L2 行为</h3>\n<p>搭载机制声称“二者共享同一组权重加载”，这句话在显存带宽账上要拆开看。共享发生在 step 粒度：一个 step 内权重只从 HBM 读一遍，decode token 与 chunk token 都消费这份已加载的权重。但共享不发生在 SM 粒度：decode 的单步前向是逐 token 的瘦 GEMM（batch 维是 token 数），chunk 的因果 attention 是块状 GEMM，两者对权重的复用模式不同，落到 L2 上的驻留行为也不同。当 chunk 较大时，chunk 的 GEMM 会以更高的算术强度反复命中同一批权重块，L2 命中率好；decode 侧则更依赖权重常驻。搭载把两者拼进同一 batch 后，L2 的替换压力介于两者之间，实际命中率取决于 chunk 与 decode 的 token 比例。</p>\n<p>代价体现在有效带宽上：若 chunk 占比过高，L2 被 chunk 的块状访问冲刷，decode 侧原本能命中的权重被挤出，decode 的 HBM 读取量上升，$B_{\\text{decode}}$ 变大，$T_{\\text{step}}$ 的带宽项被推高。这是一个不写在公式里、但在 profiler 上能直接看到的二阶效应。工程上的应对不是调 chunk_size，而是控制单 step 内 chunk token 与 decode token 的比例上限——把搭载看成一种“带宽预算的重新分配”，而不是无成本的填缝。</p>\n<p>具体例子：一个 step 里 decode 集合贡献数百个 token、搭载一个 512 token 的 chunk，chunk 的 token 数已经压过 decode，此时权重加载虽只一次，但 L2 的驻留格局被 chunk 主导，decode 的下一 step 会感受到权重冷启动的代价。把 chunk 拆成更小的块分批搭载，能让比例回到 decode 主导的一侧，代价是 prefill 被切碎、attention 效率下降——这正是 chunk_size 两难在带宽维度的另一副面孔。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-39\">三十九 · 通信：单引擎省掉的与规模上去后新增的</h3>\n<p>搭载的一大卖点是无需分离式部署，单引擎同机共卡，因此省掉了 prefill 引擎与 decode 引擎之间的 KV 传输——那笔账在分离式方案里是跨节点 NVLink 上的大块搬运，在搭载方案里直接归零。但省掉的是引擎间通信，不是全部通信。规模上去后，搭载方案在以下三处重新长出通信代价。</p>\n<ul>\n<li>张量并行/专家并行的 all-reduce 与 all-to-all：搭载 step 的 batch 里同时有 decode 与 chunk，两类 workload 的并行切分必须一致，all-reduce 的 payload 是两者之和，单 step 的集合通信量比纯 decode step 大。当 chunk 占比高时，通信时间在 $T_{\\text{step}}$ 里的份额上升，且这部分不与计算重叠得那么好，因为 chunk 的 attention 结构与 decode 不同，流水排布更难对齐。</li>\n<li>KV 块表的跨卡一致性：chunk 执行完并入请求块表这一步，若块表分片在多卡上，需要一次元数据同步。单次开销小，但每个搭载 step 都可能触发，累积起来是可观的控制面流量。</li>\n<li>rollout 与训练侧的梯度/样本回传：批次结束时统计每请求 token 与 logprob 回传训练侧，这是搭载方案固有的出站流量，规模上去后与训练侧的集合通信争抢同一张网。</li>\n</ul>\n<p>判断规模上限时，通信是一个容易被低估的先崩点：当 decode 集合与待搭载队列同时变大，单 step 的 all-reduce payload 膨胀，通信时间挤进 $T_{\\text{step}}$ 的临界路径，互补窗口被压缩。此时把 chunk 挪到通信较空闲的 step 搭载，比单纯调 chunk_size 更有效。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-40\">四十 · 功耗与热：互补不等于省电</h3>\n<p>搭载让 SM 与 HBM 在同一 step 内都被填满，这在能效上是一把双刃剑。串行 prefill/decode 时，prefill 阶段 SM 忙、HBM 闲，decode 阶段 HBM 忙、SM 闲，两个阶段各有一次“半载”运行，整机的功率曲线是两段较低的平台。搭载把两段合成一段满载，SM 与 HBM 同时拉高，单 step 的瞬时功率显著高于任一串行阶段。对 GB200/GB300 NVL72 这类机架级部署，功率是机架级预算，不是单卡预算：一个机架内多台单引擎同时进入搭载 step 的满载状态，机架功率峰值会被顶到上限，触发降频或功率封顶。</p>\n<p>降频的后果直接落在 $P_{\\text{peak}}$ 上：公式里的 $P_{\\text{peak}}$ 是标称峰值，实际运行时若因功率封顶降到标称以下，$T_{\\text{step}}$ 的算力项被同比放大，搭载的互补收益被吃掉一部分。这是一个闭环：搭载提高瞬时功率 → 触发封顶 → 有效算力下降 → 互补窗口收窄。工程上的缓解不是放弃搭载，而是让搭载 step 在时间上错峰——不同单引擎的搭载节奏错开，避免机架内同时满载；或者把 chunk 占比控制在使功率峰值留在预算内的水平，用部分互补换稳定运行。</p>\n<p>具体例子：机架内若干单引擎各自按固定 chunk_size 搭载，若它们的 step 节奏因批次起点相近而同步，功率峰值叠加；把待搭载队列的取用节奏按引擎做相位偏移，功率曲线被摊平，$P_{\\text{peak}}$ 的有效值回到标称附近，互补收益得以保留。这是调度层面的手段，不改算法本身。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-41\">四十一 · 尾延迟与规模先崩点</h3>\n<p>搭载使 decode step 的时延抖动增大，这一点前文已定性提过，这里给出它在规模上的放大机制。decode 请求的 ITL 由 $T_{\\text{step}}$ 决定，而 $T_{\\text{step}}$ 在搭载 step 里被 chunk 的算力项与带宽项共同抬高。对单个 decode 请求，它的第 $t$ 步可能恰好赶上一个大 chunk 搭载，ITL 出现尖峰；下一步没有 chunk，ITL 回落。这种交替在 decode 集合小时表现为个别请求的抖动，在 decode 集合大时表现为整批请求的同步抖动——因为搭载是批级的，所有 decode 请求共享同一个被抬高的 $T_{\\text{step}}$。</p>\n<p>尾延迟的代价落在 rollout 的 token 级超时判定上：超时阈值按稳态 ITL 设定，搭载尖峰让正常的长尾样本被误判超时，样本被丢弃或截断，训练侧看到的样本分布被系统性扭曲——被误杀的恰是那些需要更多 token 才能完成的难样本。这是搭载方案最隐蔽的失败模式：它不降低吞吐，但改变样本集合的构成，进而影响训练信号。</p>\n<p>规模上去以后，先崩的顺序可以按以下逻辑排：decode 集合增大使 $T_{\\text{step}}$ 转为算力受限，互补窗口收窄（先崩在吞吐收益上）；待搭载队列积压而 decode 集合缩小时，chunk 独占 batch，带宽利用率回落，互补对象消失（崩在利用率上）；机架功率封顶压低有效 $P_{\\text{peak}}$（崩在能效上）；最后是搭载尖峰在超大 decode 集合上同步化，尾延迟判定误杀率上升（崩在样本质量上）。前三者是性能问题，可调；最后一个是正确性问题，一旦发生，调 chunk_size 只能缓解不能消除，需要把超时判定从“按 step 计”改为“按请求的累计搭载暴露计”，让判定逻辑知道这个 step 里有没有搭载、搭载了多大的 chunk。</p>\n<p>工程判断落在具体机制上：搭载调度器应当在取 chunk 时同时输出该 step 的 chunk token 数与预计 $T_{\\text{step}}$ 抬升量，把这个元数据随 decode 请求的计时一起传给超时判定模块；判定模块按“扣除搭载抬升后的净 ITL”做超时判断，而不是按墙钟 ITL。这样尾延迟统计与训练侧样本分布才不会被搭载的批级抖动污染，规模扩展时先崩的那一环从正确性退回到性能，重新变成可调参的问题。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-42\">四十二 · 搭载批的临界规模与失效链</h3>\n<p>搭载能否成立，取决于同一 step 内两类负载是否真的同时在场。设第 <i>t</i> 步批构成为 <i>B<sub>t</sub></i> = {(x<sup>dec</sup>,1)} ∪ {(x<sup>pre</sup>,c<sub>j</sub>)}，c<sub>j</sub> ≤ chunk_size（如 512）。互补收益近似正比于 min(|D<sub>t</sub>|, |Q<sub>t</sub>|) 与 chunk 内 token 数的乘积：decode 集合太小，chunk 找不到带宽密集对象，prefill chunk 独占 batch，HBM 带宽利用率回落到纯 prefill 水平；待搭载队列积压而 decode 集合收缩，则每个 step 只能搭载一个 chunk，队列越拖越长，rollout 批次结束时间被 prefill 尾部主导。此时 T<sub>step</sub> 由 max(算力项, 带宽项) 退化为单项主导，MFU<sub>piggyback</sub> 的分子虽增、分母同步膨胀，互补增益归零。</p>\n<p>chunk_size 是固定超参，与 prompt 长度分布强耦合。chunk 过小，prefill 被切碎，chunk 内因果 attention 的有效算力密度下降，权重加载次数随 chunk 数线性上升；chunk 过大，单个 step 的算力项压过带宽项，decode token 的逐 token 时延被拉长。分布漂移（长 prompt 占比上升或下降）后原 chunk_size 失配，需重新调参，否则两类瓶颈互补失效。工程上应把 chunk_size 与 decode 集合规模的比值作为监控量，而非只盯 GPU 利用率。</p>\n<p>尾延迟是这套方案最直接的代价。搭载使 decode step 时延抖动增大：含 chunk 的 step 明显长于纯 decode step，token 级超时判定容易误杀正常长尾样本，长尾统计失真并回传训练侧，污染样本分布。缓解手段是给搭载 step 单独设超时阈值、按 step 类型分层统计 token 时延，而不是用统一 token 级 SLO 卡所有 step。</p>\n<table class=\"mini\"><thead><tr><th>状态</th><th>主导瓶颈</th><th>后果</th></tr></thead><tbody><tr><td>decode 集合充足、队列非空</td><td>算力与带宽互补</td><td>利用率高于串行</td></tr><tr><td>decode 集合过小</td><td>prefill 独占 batch</td><td>带宽利用率回落</td></tr><tr><td>chunk_size 失配</td><td>单项主导</td><td>互补失效、抖动放大</td></tr></tbody></table>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-43\">四十三 · 精度漂移：搭载批内两类 workload 的数值一致性</h3>\n<p>搭载批的构成决定了精度问题不是单点故障，而是耦合故障。一个 step 内同时存在 decode token 的单步前向与 chunk token 的 chunk 内因果 attention，二者共享同一组权重加载，因此权重一旦被量化到 NVFP4 或 FP8，两类 workload 必须落在同一量化档位上。若 decode 侧沿用较高精度而 prefill chunk 侧走低精度路径，同一个 KV 块表里会混入两套数值尺度的 K/V，后续 decode step 读取这些块时出现系统性偏移——表现为 logprob 缓慢漂移而非突然崩溃，最难定位。诊断手段是给每个 chunk 的 KV 块打上量化档位标签，在块表合并时校验标签一致性，不一致即拒绝合并并回退该 chunk 到高精度重算。代价是显存：标签与回退副本占用额外 KV 空间，在长 prompt 高并发时直接压缩可驻留请求数。具体例子：一个 512 token 的 chunk 在 FP8 路径下算出 K/V，并入块表后该请求转入 decode 集合，若其后续 decode step 走 NVFP4 权重路径，attention 输出的相对误差会随 decode 步数累积，rollout 回传训练侧的 logprob 与真实分布偏离，梯度信号被污染。</p>\n<div class=\"formula\">$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>这条公式本身就是诊断工具：把实测的 $T_{\\text{step}}$ 与公式预测值对比，若实测显著高于 max 项，说明瓶颈不在算力也不在带宽，而在同步或调度开销；若实测贴近带宽项而算力项远低，说明 chunk 切得太碎、attention 效率下降，算力没被吃满。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-44\">四十四 · OOM 的三条路径与块表水位监控</h3>\n<p>搭载机制下的 OOM 不来自单请求超长，而来自块表合并时机与待搭载队列的叠加。第一条路径：chunk 执行完并入块表时，若该请求的块表已接近容量上限，合并动作触发一次不可分割的分配，瞬时显存峰值超过稳态。第二条路径：待搭载队列积压，多个长 prompt 的 chunk 同时在途，每个 chunk 的中间 KV 尚未并入块表却已占用临时缓冲，队列深度乘以 chunk_size 构成隐式显存开销。第三条路径：decode 集合缩小但队列未清空，chunk 独占 batch，为维持 batch 形状而填充的 padding 与临时激活抬高峰值。监控应盯块表水位而非仅盯总显存：按请求维度记录已分配块数、待合并块数、临时缓冲字节数，三者之和超过阈值即触发队列限流。工程判断是给待搭载队列设硬上限，上限由 chunk_size 与 decode 集合规模共同决定——decode 集合过小则搭载收益下降，此时宁可暂停搭载、让 chunk 走独立 prefill 批次，也不让队列无限积压。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-45\">四十五 · 批抖动与路由不均：抖动源在 chunk 边界</h3>\n<p>搭载使 decode step 时延抖动增大，抖动源不是 decode 本身，而是每个 step 搭载的 chunk 长度与 chunk 内因果 attention 的形状变化。固定 chunk_size 下，最后一个 chunk 往往不足额，形成长短不一的 step；若调度器按请求到达顺序取 chunk，相邻 step 的算力需求差异可达数倍，$T_{\\text{step}}$ 在算力项与带宽项之间来回切换，表现为批抖动。路由不均则是另一层：多卡或多引擎部署时，长 prompt 的 chunk 若按请求哈希路由，某些卡持续收到长 prompt 而另一些卡 decode 集合偏大，卡间负载失衡，整体吞吐被最慢卡钉死。诊断靠 per-step 的算力项与带宽项实测比值，比值剧烈震荡即抖动；靠 per-rank 的 chunk 队列深度与 decode 集合规模对比，持续偏离均值即路由不均。缓解手段是把 chunk 入队改为按长度分桶、跨 step 轮转取用，使相邻 step 的搭载负载平滑；路由侧改为按队列深度而非请求哈希做 chunk 级再平衡。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-46\">四十六 · 尾延迟尖刺：token 级超时误杀长尾样本</h3>\n<p>尾延迟尖刺的直接后果是 token 级超时判定误杀正常长尾样本。搭载批里，一个 decode 请求的某一步恰好与一个大 chunk 同批，该 step 的 $T_{\\text{step}}$ 被 chunk 的算力项拉长，decode 请求的 token 间隔随之拉长；若超时阈值按稳态 step 时延设定，这个请求会被判超时并丢弃，但它其实是正常长尾。丢弃改变样本集合，长尾统计失真并影响训练侧样本分布——这是搭载机制对 RL rollout 最隐蔽的伤害。诊断要区分“step 变慢”与“请求变慢”：记录每个 decode token 的发射 step 编号与该 step 搭载的 chunk 长度，若超时样本集中在搭载了大 chunk 的 step 上，说明是搭载拖累而非请求本身异常。回滚策略是把超时判定从 wall-clock 改为按 step 计数，或对搭载了 chunk 的 step 放宽阈值；更稳的做法是给长尾样本单独打标、延迟判定，等队列清空后再统一结算，避免在抖动窗口内误杀。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-47\">四十七 · 监控面与回滚开关</h3>\n<p>监控面按四层组织：step 层记录 $T_{\\text{step}}$、算力项与带宽项实测、搭载 chunk 长度分布；请求层记录每请求的 chunk 数、块表水位、token 间隔分布；队列层记录待搭载队列深度与等待时长；rank 层记录 chunk 队列与 decode 集合的均衡度。四个指标对应四类失败模式：算力带宽比值震荡对应批抖动，块表水位对应 OOM，队列深度对应搭载失效，token 间隔长尾对应尾延迟误杀。回滚开关要分级：一级回滚把 chunk_size 减半并暂停搭载一个批次周期，用于抖动与尾延迟；二级回滚把待搭载队列冻结、chunk 转独立 prefill 批次，用于 OOM 与队列积压；三级回滚整体退回串行 prefill/decode，用于精度漂移无法在块表层拦截的情形。回滚必须可逆且带状态快照——块表标签、队列内容、decode 集合成员在回滚点冻结，恢复时按快照重建，避免回滚本身引入新的块表不一致。chunk_size 是固定超参，prompt 长度分布漂移时需重新调参，否则算力与带宽互补失效；监控面应把 prompt 长度分布的滑动分位数纳入，分布偏移超过阈值即提示重调 chunk_size，而不是等 MFU 掉下去才反应。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要监控量</th><th>回滚级别</th></tr></thead><tbody><tr><td>精度漂移</td><td>块表量化标签一致性</td><td>三级</td></tr><tr><td>OOM</td><td>块表水位+队列深度</td><td>二级</td></tr><tr><td>批抖动</td><td>算力/带宽实测比值</td><td>一级</td></tr><tr><td>路由不均</td><td>per-rank 队列与 decode 规模</td><td>一级</td></tr><tr><td>尾延迟尖刺</td><td>token 间隔与搭载 chunk 长度关联</td><td>一级+延迟判定</td></tr></tbody></table>\n<p>最后落在工程判断上：搭载机制的失败几乎都发生在 chunk 边界——块表合并点、队列取用点、step 切换点。把监控探针钉在这三个边界上，比盯全局 MFU 更早发现问题；回滚设计也要围绕边界做，冻结队列与块表快照，让回滚成为一次边界状态的重建而非全局重启。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-48\">四十八 · 搭载失效的五种形态与可观测抓手</h3>\n<p>分块预填搭载解码的收益来自一个隐含前提：每个 decode step 里既有足够多的 decode token 提供带宽压力，又有长度受控的 prefill chunk 提供算力压力，两者在同一批内互补。一旦这个前提被打破，机制不会优雅退化，而是以几种可辨识的形态失效。第一种是<strong>配方失配</strong>：chunk_size 是固定超参，prompt 长度分布漂移后，chunk 过小则 prefill 被切碎、chunk 内因果 attention 的有效算力密度下降，chunk 过大则单步时延被 prefill 主导、decode 被拖慢。判据是看搭载批的实际构成 $B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\ c_j\\le\\text{chunk\\_size}$ 中 $|\\mathcal{D}_t|$ 与 $\\sum c_j$ 的比例是否偏离设计点，以及单步时间是否从带宽受限翻转为算力受限——用 $T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$ 反推哪一项在主导，若 max 的两项长期由算力项胜出，说明 chunk 切得过碎或过大。第二种是<strong>队列积压而 decode 集合萎缩</strong>：待搭载队列 $\\mathcal{Q}_t$ 仍有 chunk，但 $\\mathcal{D}_t$ 已缩到很小，chunk 独占 batch，互补对象消失，带宽利用率回落，此时搭载退化为串行 prefill 且更差——因为 chunk 之间没有 decode 的权重加载摊薄。监控抓手是每步记录 $|\\mathcal{D}_t|$、$|\\mathcal{Q}_t|$ 与 chunk 平均长度，三者同时进入时序面板。</p>\n<p>第三种是<strong>批抖动与尾延迟尖刺</strong>：搭载把两类 workload 塞进同一 step，decode 的 token 级时延分布从窄带变成带长尾的宽带。对 RL rollout 尤其致命——token 级超时判定会把正常的长尾样本误杀，长尾统计失真，进而扭曲回传训练侧的样本分布。这里不能只看均值，要按请求维度记录每 step 的 decode 间隔，用分位数而非平均判断：若 P99 间隔相对 P50 的比值在搭载开启后系统性抬升，说明 chunk 长度波动正在向 decode 传导。工程上可给 chunk 长度加软上限并在队列侧做长度分桶，把超长 chunk 延后到 decode 集合较满的 step 搭载，用调度换抖动。第四种是<strong>精度不一致</strong>：搭载 batch 内 decode token 与 chunk token 共享同一组权重加载，若两类路径走了不同量化档位（例如 chunk 走 FP8、decode 走 NVFP4），同一 step 内会出现数值口径分裂，表现为 logprob 偏移与长尾样本的似然异常，而这类问题在吞吐指标上完全不可见。部署时必须保证搭载 batch 内两类 workload 的数值精度一致，并把每请求回传的 logprob 与参考实现的偏差纳入监控。第五种是<strong>OOM 与 KV 块表碎片</strong>：chunk 执行完其 KV 块并入对应请求的块表，块表在搭载期间同时承载“未完成请求的已算 chunk”与“在跑 decode 请求的增长 KV”，显存峰值出现在队列最深、decode 集合最大的交叉点，而非任一单独阶段。容量规划要按这个交叉点而非稳态 decode 显存估算。</p>\n<p>回滚策略要按失效形态分层，而不是一刀切关掉搭载。配方失配属于参数问题，回滚动作是冻结当前 chunk_size 并按最近窗口的 prompt 长度分布重算，同时保留旧值作为对照；队列积压属于调度问题，回滚动作是临时关闭搭载、让队列走独立 prefill 批，待 $\\mathcal{D}_t$ 恢复后再开；尾延迟尖刺属于 SLO 问题，回滚动作是收紧 chunk 软上限而非关闭机制；精度不一致属于部署问题，回滚动作是统一量化档位后重放同一批请求比对 logprob；OOM 属于容量问题，回滚动作是压低队列深度上限与并发 decode 数。判断是否回滚的量化依据可直接用搭载批的 MFU 口径：$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}}$$ 当该值连续若干 step 低于关闭搭载时的串行基线，说明互补已失效，此时搭载只剩抖动代价。以一个长短 prompt 混合的 rollout 批次为例：若某窗口内 chunk 平均长度逼近 chunk_size 上限而 decode 集合规模持续下滑，MFU 会先于尾延迟指标恶化，这正是把 MFU 与 $|\\mathcal{D}_t|/|\\mathcal{Q}_t|$ 并列做成同一张时序图的理由——前者告诉你收益是否还在，后者告诉你失效属于哪一类，两者合起来才能在抖动传导到训练侧之前完成回滚决策。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-49\">四十九 · 搭载失效的四种形态与回滚判据</h3>\n<p>搭载机制的健康前提是「decode 集合足够大、chunk 队列不空、chunk_size 与 prompt 长度分布匹配」。任一前提破裂，互补即失效。第一种是<b>配方失配</b>：chunk 过小（远低于 512 token 量级）使 prefill 被切碎、chunk 内因果 attention 效率下降，权重加载次数上升而有效算力占比下降；chunk 过大则单个 decode step 被拖长，decode 请求的 token 级时延被 prefill 挤占。判据可写成搭载批的实际构成比：</p>\n<div class=\"formula\">$$\\rho_t=\\frac{\\sum_{j\\in\\mathcal{Q}_t} c_j}{\\sum_{i\\in\\mathcal{D}_t} 1+\\sum_{j\\in\\mathcal{Q}_t} c_j},\\quad \\rho_t\\to 0 \\text{ 或 } \\rho_t\\to 1 \\text{ 均表示互补失效}$$</div>\n<p>$\\rho_t$ 长期贴近 0 说明队列空、搭载无对象；贴近 1 说明 decode 集合萎缩、chunk 独占 batch，HBM 带宽利用率回落。第二种是<b>队列积压与 decode 萎缩并发</b>：rollout 批次尾部，decode 集合逐步清空而待搭载队列仍有 chunk，此时每步只剩 prefill，算力密集但带宽闲置，等于退化为串行预填。第三种是<b>批抖动与尾延迟尖刺</b>：搭载使 decode step 时延方差变大，token 级超时判定会把正常的长尾样本误杀，长尾统计失真并反向污染训练侧样本分布——这是比吞吐下降更隐蔽的代价。第四种是<b>精度不一致</b>：chunk 与 decode token 共享同一组权重加载，若两条路径落入不同量化档位（如 NVFP4 与 FP8 混用），logprob 统计会出现系统性偏移，而 RL 训练侧对 logprob 偏差极其敏感。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要观测</th><th>处置</th></tr></thead><tbody><tr><td>$\\rho_t$ 持续偏低</td><td>队列深度、decode 集合规模</td><td>缩小 chunk_size 或延后批次收尾</td></tr><tr><td>decode step 时延方差抬升</td><td>P99 step 时延与超时误杀率</td><td>临时下调搭载比，超时判定改用分位阈值</td></tr><tr><td>logprob 偏移</td><td>同请求双路径 logprob 抽样比对</td><td>回滚至统一精度档位，暂停搭载</td></tr></tbody></table>\n<p>监控应落在三个量上：每 step 的 $\\rho_t$、decode 集合规模与队列深度之比、以及搭载批与非搭载批的 step 时延分布对比。回滚不是关掉引擎，而是把搭载开关降级为「按比例搭载」——每 N 个 decode step 只搭载一个 chunk，让时延分布回到可判定区间；若精度告警触发，则直接回滚到统一量化档位并重放该批次，因为 logprob 一旦污染，训练侧无法事后修正。工程判断是：搭载的收益来自互补，代价来自抖动，因此回滚阈值应绑在抖动统计而非平均吞吐上。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-50\">五十 · 同族算法的选择维度：先问“瓶颈在哪一侧”</h3>\n<p>分块预填搭载解码不是孤立的技巧，它属于“让算力密集与带宽密集负载在同一批次内互补”这一族。选型时第一个问题不是“哪个算法更强”，而是当前 rollout 引擎的瓶颈落在哪一侧。若瓶颈在预填侧——长 prompt 反复进入、prefill 阶段 HBM 带宽大量闲置——那么前缀 KV 共享与本算法是直接候选；若瓶颈在解码侧的算力空转，搭载就是唯一能在单引擎内同时填满 SM 与 HBM 的选项。若瓶颈根本不在单引擎内部，而在多实例间的负载不均，则分离式预填/解码与 KV 中心池化才是正解，搭载只会把抖动引入一个本已脆弱的单实例。</p>\n<p>第二个维度是“是否允许改变样本集合”。在线剪枝通过放弃低价值轨迹换吞吐，它改变的是训练侧看到的分布；搭载不改变样本集合，只改变执行时序，因此对训练语义是中性的。这一点在 RL 场景里价值很高：当样本分布本身是训练信号的一部分时，任何剪枝都要额外论证，而搭载不需要。第三个维度是部署形态：单引擎同机共卡、训练与 rollout 抢卡，搭载的边际收益最大；一旦已经做了物理分离，搭载的互补对象（同批次内的 decode 集合）就不在同一张卡上，机制失效。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>消除的浪费</th><th>是否改样本</th><th>部署前提</th><th>主要代价</th></tr></thead><tbody><tr><td>分块预填搭载解码</td><td>prefill 带宽闲置 + decode 算力闲置</td><td>否</td><td>单引擎同机共卡</td><td>decode step 时延抖动</td></tr><tr><td>前缀 KV 共享</td><td>同 prompt 重复预填</td><td>否</td><td>需前缀可复用</td><td>前缀命中率低时收益塌陷</td></tr><tr><td>预填解码分离</td><td>两类负载互相拖累</td><td>否</td><td>两套资源池 + 传输</td><td>KV 跨池搬运带宽</td></tr><tr><td>KV 中心池化</td><td>KV 重复驻留与孤岛</td><td>否</td><td>池化存储 + 高带宽互联</td><td>访问延迟与一致性</td></tr><tr><td>在线剪枝</td><td>低价值轨迹的算力</td><td>是</td><td>可判定价值</td><td>分布偏移风险</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-51\">五十一 · 与前缀 KV 共享的分工：空间复用 vs 时间互补</h3>\n<p>前缀 KV 共享在“空间”维度做文章：多个请求携带相同前缀时，只预填一次，后续请求直接引用已有 KV 块。搭载在“时间”维度做文章：不同 prompt 的 prefill chunk 被塞进别人的 decode step，互补的是同一时刻的两种资源压力。二者的适用条件几乎正交——前缀共享要求请求间存在可识别的高重合前缀（系统提示、few-shot 模板、多轮对话历史），命中率决定收益；搭载要求 decode 集合足够大、prompt 长度分布与 chunk_size 匹配，与内容重合无关。</p>\n<p>工程上二者可以叠加，但叠加顺序有讲究：先做前缀匹配，把命中前缀的请求从待搭载队列里摘出去（它们的 prefill 已被消除），剩余未命中的 chunk 才进入搭载队列。若顺序颠倒，搭载队列里会混入大量本可零成本完成的 prefill，白白占用 decode step 的算力预算。代价上，前缀共享的索引查找是每请求一次的内存操作，量级远小于一个 chunk 的前向；而搭载的代价是 decode step 的时延方差，二者不在同一量纲，不能互相替代。</p>\n<div class=\"formula\">$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$</div>\n<p>这个式子给出选型的定量判据：搭载的收益来自分子中两项相加而分母只取 max，即两类负载共享同一个 step 的时间下界；一旦 decode 集合缩小到 $F_{\\text{decode}}$ 与 $B_{\\text{decode}}$ 都远小于 chunk 项，max 由 chunk 单独决定，互补消失，此时前缀共享或剪枝才是提效手段。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-52\">五十二 · 与分离式预填/解码的取舍：抖动预算换部署复杂度</h3>\n<p>分离式方案把 prefill 与 decode 放到不同资源池，各自按自身瓶颈配比，理论上限更高，但引入 KV 跨池搬运——每个请求的 KV 块要从预填池传到解码池，搬运量与 prompt 长度成正比，走 NVLink 5 或 NIXL 通路时占用互联带宽，且需要两套调度器协同。搭载把这笔搬运费换成时延抖动费：不搬 KV，但 decode step 的时长被 chunk 拉长，token 级超时判定开始误杀正常长尾样本。</p>\n<p>决策要看抖动是否可被上层吸收。若 rollout 的超时是按请求级（整条轨迹完成时间）判定，搭载引入的 step 级抖动会被平均掉，代价可接受；若超时是按 token 级（首 token 或每 token 间隔）判定，抖动直接触发误杀，长尾统计失真并污染训练侧样本分布，此时应选分离式，用确定性的 prefill 池时延换掉抖动。另一个判据是规模：分离式需要足够多的并发请求才能喂饱两个池，小规模 rollout 下预填池会长期空转，搭载在单引擎内反而更省。</p>\n<ul>\n<li>请求级超时 + 单机共卡 + 长短 prompt 混合 → 搭载。</li>\n<li>token 级超时 + 大规模并发 + 互联带宽充裕 → 分离式。</li>\n<li>两者都不满足但前缀重合度高 → 先做前缀共享，再评估是否需要搭载。</li>\n</ul>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-53\">五十三 · 与在线剪枝的边界：提效不等于改分布</h3>\n<p>在线剪枝在轨迹粒度上做取舍，放弃低价值样本以节省算力；搭载在 step 粒度上做拼装，不丢弃任何样本。二者的选择取决于“算力节省”与“分布保真”哪个是硬约束。RL 训练中，若采样分布本身参与优势估计，剪枝会引入偏差，需要重要性修正；搭载没有这个负担，代价只在时延侧。反过来，若算力极度紧张且剪枝判据可靠（例如明显低回报的早期轨迹），剪枝的节省幅度远大于搭载——搭载最多把 MFU 从“两类瓶颈交替闲置”拉到“单 step 内互补”，上限受 $P_{\\text{peak}}$ 与 $BW_{\\text{HBM}}$ 的比值约束，而剪枝直接减少总工作量。</p>\n<p>伪代码层面的判据可以写成：若单位算力节省 $\\Delta F_{\\text{prune}} / F_{\\text{total}}$ 大于搭载可回收的闲置比例 $1-\\text{MFU}_{\\text{piggyback}}$，且剪枝判据的误判率低于可接受阈值，则剪枝优先；否则搭载。注意搭载的回收比例在 decode 集合过小时会迅速衰减，而剪枝的节省与并发规模无关，这是小规模场景下剪枝反而更稳的原因。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-54\">五十四 · 决策表：把适用条件压成可执行的判断链</h3>\n<p>把前述维度合成一条判断链，避免在部署时反复试参。第一问：prefill 与 decode 是否在同一引擎、同一批卡上？否，则搭载不成立，转分离式或池化。第二问：decode 集合规模是否足以与 chunk 形成互补？若 decode 集合长期小于 chunk 所需算力，搭载退化为 chunk 独占 batch，带宽利用率回落，应改用前缀共享或增大并发。第三问：超时判定粒度是请求级还是 token 级？token 级则需为搭载单独放宽超时或改用分离式。第四问：prompt 长度分布是否稳定？分布漂移会使固定 chunk_size 失配，需按分布重调或改用自适应 chunk。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>搭载</th><th>前缀共享</th><th>分离式</th><th>剪枝</th></tr></thead><tbody><tr><td>单引擎同机共卡</td><td>首选</td><td>可叠加</td><td>不适用</td><td>可叠加</td></tr><tr><td>decode 集合偏小</td><td>收益衰减</td><td>首选</td><td>需大规模</td><td>首选</td></tr><tr><td>token 级超时</td><td>需放宽阈值</td><td>无影响</td><td>首选</td><td>无影响</td></tr><tr><td>前缀重合度高</td><td>先摘除命中项</td><td>首选</td><td>可叠加</td><td>无关</td></tr><tr><td>分布漂移频繁</td><td>需重调 chunk</td><td>无影响</td><td>无影响</td><td>判据需重校</td></tr></tbody></table>\n<p>表中“可叠加”不是无条件叠加：搭载与剪枝叠加时，剪枝先决定哪些轨迹进入 rollout，搭载再决定剩余轨迹的执行时序，顺序不可颠倒，否则被剪枝的轨迹已占用 chunk 预算。搭载与前缀共享叠加时则相反，前缀匹配必须先于入队。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-55\">五十五 · 规模上限与工程判断的落点</h3>\n<p>搭载的规模上限由两个量夹住：chunk_size 决定单个 step 能吸收多少 prefill 算力，decode 集合规模决定互补对象是否存在。当 decode 集合的每步算力需求已经接近 $P_{\\text{peak}}$，再塞 chunk 只会把 $T_{\\text{step}}$ 从算力界推到算力界之上，收益为零；当 decode 集合的带宽需求已接近 $BW_{\\text{HBM}}$，chunk 的权重加载会与 decode 争带宽，max 项切换到带宽侧，互补同样失效。因此搭载的有效区间是“decode 侧两项都未饱和、chunk 侧两项都未饱和”的中间地带，这个地带随并发数移动，不能靠固定 chunk_size 一劳永逸。</p>\n<p>工程判断落在自适应上：以 $T_{\\text{step}}$ 的实测值与 max 公式两界的比值作为反馈信号，若算力界长期主导则增大 chunk_size 吸收更多 prefill，若带宽界主导则减小 chunk_size 或暂停搭载，让 decode 回到纯解码节奏。这个反馈环不需要改模型，只需在调度器里维护一个滑动窗口的 step 时长统计。真正需要警惕的是待搭载队列积压而 decode 集合同时缩小——此时 chunk 独占 batch，带宽利用率回落，机制从“互补”退化为“串行”，调度器应主动暂停搭载并等待 decode 集合恢复，而不是继续往 batch 里塞 chunk。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-rollout-sec-56\">五十六 · 搭载法的失效边界与同族算法选型判据</h3>\n<p>搭载法把两类瓶颈的互补建立在“同一 step 内两类 workload 同时在场”这一前提上，因此它的失效条件可以用搭载批的构成式直接读出：$$B_t=\\{(x_i^{\\text{dec}},1)\\}_{i\\in\\mathcal{D}_t}\\cup\\{(x_j^{\\text{pre}},c_j)\\}_{j\\in\\mathcal{Q}_t},\\quad c_j\\le \\text{chunk\\_size}$$。当 $|\\mathcal{D}_t|$ 收缩而 $\\mathcal{Q}_t$ 积压时，chunk 独占 batch，带宽利用率回落到串行 prefill 的水平，互补收益归零；反之 decode 集合庞大而队列见底时，step 退化为纯 decode，算力继续闲置。工程判据是盯住 $\\mathcal{D}_t$ 与 $\\mathcal{Q}_t$ 的比值而非 GPU 利用率本身——利用率是结果，队列深度才是可调的自变量。规模上限同样受此约束：decode 集合过小则搭载收益下降，具体上限取决于 chunk_size 与在跑请求数，需在容量规划时按最坏队列形态留出余量。</p>\n<p>chunk_size 是固定超参，这决定了它与 prompt 长度分布的耦合方式。过小则 prefill 被切碎、chunk 内因果 attention 的有效长度缩短、attention 效率下降；过大则单个 step 被 prefill 主导，decode 侧 token 间时延被拖慢，token 级 SLO 直接受损。调参依据应是长度分布的尾部而非均值：长 prompt 占比高时向上调，短 prompt 为主时向下调。分布漂移（例如训练阶段切换导致 rollout 样本长度整体右移）后若不重新调参，两类瓶颈的互补就会失效，表现为 MFU 表面持平而尾延迟恶化。可用下式判断搭载是否仍在收益区：$$\\text{MFU}_{\\text{piggyback}} = \\frac{F_{\\text{decode}} + F_{\\text{prefill\\_chunk}}}{T_{\\text{step}}\\cdot P_{\\text{peak}}},\\quad T_{\\text{step}} \\approx \\max\\left(\\frac{F_{\\text{decode}}+F_{\\text{prefill\\_chunk}}}{P_{\\text{peak}}},\\ \\frac{B_{\\text{decode}}+B_{\\text{prefill\\_chunk}}}{BW_{\\text{HBM}}}\\right)$$，当 $T_{\\text{step}}$ 由带宽项而非算力项决定时，说明 chunk 配比已偏向带宽密集侧，继续加大 chunk 只会拉长 step 而不提升 MFU。</p>\n<p>时延抖动是这一方案最容易被低估的代价。搭载使 decode step 的执行时间随 chunk 长度波动，token 级超时判定会把正常的长尾样本误杀，长尾统计失真后回传训练侧的样本分布随之偏移——这不是性能问题而是正确性问题。因此该方案适合以 GPU 利用率为目标、对单 token 时延不敏感的场景；若 SLO 落在 token 级尾延迟上，应改用分离式预填/解码把两类流量在部署层隔离，代价是额外的 KV 传输与引擎间协调。</p>\n<table class=\"mini\"><thead><tr><th>相邻算法</th><th>作用维度</th><th>与本方案的关系</th><th>选用条件</th></tr></thead><tbody><tr><td>Rollout 前缀 KV 共享</td><td>消除同 prompt 重复预填</td><td>正交，可叠加</td><td>同 prompt 多采样、前缀重复率高</td></tr><tr><td>在线 Rollout 剪枝</td><td>缩减样本集合</td><td>改变样本分布，本方案不改</td><td>低价值轨迹占比高、可接受分布偏移</td></tr><tr><td>分离式预填/解码</td><td>部署层隔离两类流量</td><td>替代方案，需跨引擎传 KV</td><td>token 级尾延迟为硬 SLO</td></tr><tr><td>本方案（分块搭载）</td><td>时间维度拼批</td><td>单引擎、不改样本集合</td><td>长短 prompt 混合、训练与 rollout 同机共卡</td></tr></tbody></table>\n<p>选型顺序应是：先看 SLO 是否落在 token 级尾延迟——是则排除搭载，走分离式；再看样本集合是否允许裁剪——允许则剪枝优先，因为它直接减少总算力需求；最后在必须保留全样本、且训练与 rollout 共卡的条件下，用搭载法提升单引擎利用率，并把前缀 KV 共享作为正交增益叠加。搭载 batch 内两类 workload 必须保持数值精度一致，量化档位不统一会破坏共享权重加载的前提，这是部署前必须核对的硬约束。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 离策略程度与陈旧度控制</td></tr><tr><td>解决什么</td><td>RL rollout中长prompt的prefill是算力密集但显存带宽利用率低的阶段，而decode是带宽密集阶段；…</td></tr><tr><td>一句话机制</td><td>把长prompt的prefill切成固定大小的chunk，每个decode step搭载一个prefill chunk…</td></tr><tr><td>代价与失效</td><td>chunk_size是固定超参，chunk过小则prefill被切碎、attention效率下降，chunk过大则decode被拖慢，需按…</td></tr><tr><td>后继</td><td>奖励模型分离式服务</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-chunked-prefill-piggyback-rollout · 共 8 个片段</p>\n";break;}}})();
